function newsItem(item){return !!item&&typeof item==='object'&&!Array.isArray(item)&&['id','title','category','banner','url'].every(key=>item[key]==null||typeof item[key]==='string');}
function newsRows(response){if(response?.status!==200)return null;let body=response.data;if(typeof body==='string'){try{body=JSON.parse(body);}catch{return null;}}return body&&typeof body==='object'&&!Array.isArray(body)&&Array.isArray(body.message)&&body.message.every(newsItem)?body.message:null;}
