async function api(path,{method='GET',body}={}){
  const multi=body instanceof FormData;
  const res=await fetch(path,{method,credentials:'same-origin',cache:'no-store',headers:{...(body&&!multi?{'Content-Type':'application/json'}:{}),...(method==='POST'?{'X-CSRF-Token':state.csrfToken}:{})},...(body?{body:multi?body:JSON.stringify(body)}:{})});
  let data;
  try{data=await res.json();}catch{throw new Error('Respons layanan lokal tidak dapat dibaca.');}
  if(!res.ok||data.ok===false){
    const details=data.error?.details;
    const networkCode=typeof details?.networkCode==='string'&&/^[a-z0-9_.:-]{1,80}$/i.test(details.networkCode)?details.networkCode:null;
    const requestId=typeof details?.requestId==='string'&&/^[a-z0-9_-]{1,128}$/i.test(details.requestId)?details.requestId:null;
    const error=new Error([data.error?.message||`Permintaan gagal (${res.status}).`,details?.code,details?.message,networkCode?`Kode jaringan: ${networkCode}`:null,requestId?`ID permintaan: ${requestId}`:null].filter(Boolean).join(' · '));
    error.code=data.error?.code||String(res.status);
    throw error;
  }
  return data;
}
