function notice(message,kind='info'){return `<div class="notice notice-${kind}" role="${kind==='error'?'alert':'note'}">${icon(kind==='error'?'warning':'info',18)}<div>${message}</div></div>`;}
function empty(t,p,i='folder'){return `<div class="empty-state"><span>${icon(i,28)}</span><h3>${t}</h3><p>${p}</p></div>`;}
function loginCard(){if(state.authenticated)return `<section class="panel login-panel"><div class="card-title"><span class="square-icon mint">${icon('shield')}</span>${badge('Sesi aktif','success')}</div><h2>Anda sudah masuk</h2><p>Gunakan layanan untuk membaca data atau menyiapkan pengiriman.</p><div class="account-name">${icon('user')}<div><strong>${esc(state.user?.username||'Pengguna')}</strong><small>${esc(state.user?.email||'Akun terautentikasi')}</small></div></div><a class="button full" href="#/services">Buka layanan ${icon('arrow',16)}</a><button class="button secondary full" data-action="logout">Keluar dari akun</button></section>`;return `<section class="panel login-panel"><div class="card-title"><span class="square-icon">${icon('lock')}</span>${badge('AKUN SENTUH TANAHKU')}</div><h2>Masuk ke akun Anda</h2><p>Gunakan akun yang biasa dipakai di aplikasi Sentuh Tanahku.</p><form id="login-form"><label>Nama pengguna<input name="username" autocomplete="username" placeholder="Masukkan nama pengguna" required maxlength="200" ${state.connection.configured?'':'disabled'}></label><label>Kata sandi<div class="password-input"><input name="password" id="password" type="password" autocomplete="current-password" placeholder="Masukkan kata sandi" required maxlength="1000" ${state.connection.configured?'':'disabled'}><button type="button" data-action="password" aria-label="Tampilkan kata sandi">${icon('eye',17)}</button></div></label><div id="login-error" class="inline-error" role="alert"></div><button type="submit" class="button full" ${state.connection.configured&&!state.loading&&!authPending&&!logoutPending?'':'disabled'}>Masuk & hubungkan ${icon('arrow',16)}</button></form>${state.connection.configured?`<p class="privacy-note">${icon('shield',14)} Kata sandi tidak disimpan oleh workspace.</p>`:`<div class="login-connection-note">${icon('info',16)}<span>${esc(state.connection.reason||'Konfigurasi koneksi belum tersedia.')} <a href="#/account">Detail koneksi</a></span></div>`}</section>`;}
function catalog(docs=false){const all=docs?state.operations.filter(o=>/berkas|sert|brankas|document|koleksi|collection/i.test(`${o.endpoint} ${o.group} ${o.label}`)):state.operations;const groups=[...new Set(all.map(o=>o.group))].sort();const matches=all.filter(o=>(group==='Semua'||o.group===group)&&(filter==='Semua'||(filter==='Dapat diuji')===(ready(o)||login(o)))&&`${o.label} ${o.endpoint} ${o.group}`.toLowerCase().includes(search.toLowerCase()));return `${head(docs?'DOKUMEN PERTANAHAN':'KATALOG LAYANAN',docs?'Dokumen & berkas':'Layanan Sentuh Tanahku',docs?'Buka fungsi sertipikat, berkas, koleksi, dan dokumen akun Anda.':'Pilih fungsi untuk melihat parameter dan menguji layanan yang sudah dipetakan.')}<div class="catalog-toolbar"><label class="search-box">${icon('search',19)}<input id="catalog-search" type="search" aria-label="Cari layanan" placeholder="Cari layanan, berkas, atau fungsi…" value="${esc(search)}"></label><label class="filter-select"><span class="sr-only">Kelompok layanan</span><select id="group-filter"><option>Semua</option>${groups.map(g=>`<option ${g===group?'selected':''}>${esc(g)}</option>`).join('')}</select></label><label class="filter-select"><span class="sr-only">Status layanan</span><select id="status-filter">${['Semua','Dapat diuji','Perlu pemetaan'].map(f=>`<option ${f===filter?'selected':''}>${f}</option>`).join('')}</select></label></div><div class="catalog-summary"><span>${matches.length} operasi</span><span><i class="legend-dot green"></i>Dapat diuji <i class="legend-dot amber"></i>Perlu pemetaan</span></div>${state.catalogError?notice(esc(state.catalogError),'error'):''}${matches.length?`<div class="operation-grid">${matches.map(o=>`<button class="operation-card" data-action="operation" data-id="${esc(o.id)}"><div class="operation-meta"><span class="operation-group">${esc(o.group)}</span>${badge(status(o),ready(o)||login(o)?'success':'warning')}</div><h3>${esc(o.label)}</h3><p>${esc(o.description||`${o.method} · ${o.endpoint}`)}</p><div class="operation-footer"><span>${o.fields.length} parameter${needsAuth(o)?' · Akun diperlukan':''}</span>${icon('arrow',17)}</div></button>`).join('')}</div>`:empty(state.loading?'Memuat katalog…':'Tidak ada layanan yang cocok','Coba kata kunci atau kelompok layanan lain.','search')}<p class="catalog-footnote">“Dapat diuji” berarti struktur request tersedia. Penerimaan server dan kesetaraan dengan alur Android perlu diuji.</p>`;}
function field(f,i){const locked=f.source==='constant'||f.source==='session';const required=f.clientRequired?'required':'';const value=f.source==='session'?'Dari sesi akun':f.default??'';let control;if(f.type==='file')control=`<input id="param-${i}" name="${esc(f.path)}" type="file" ${required} ${f.accept?`accept="${esc(f.accept)}"`:''}>`;else if(f.type==='boolean')control=`<select id="param-${i}" name="${esc(f.path)}" ${required} ${locked?'disabled':''}><option value="">Tidak diisi</option><option value="true" ${value===true?'selected':''}>Ya (true)</option><option value="false" ${value===false?'selected':''}>Tidak (false)</option></select>`;else control=`<input id="param-${i}" name="${esc(f.path)}" type="${/password/i.test(f.path)?'password':['number','integer'].includes(f.type)&&!locked?'number':'text'}" ${['number','integer'].includes(f.type)?'step="any"':''} value="${esc(value)}" ${required} ${locked?'readonly':''} autocomplete="off" placeholder="${esc(f.placeholder||(f.hideType?f.label:f.path))}">`;return `<label class="parameter-field"><span>${esc(f.label||f.path)}${required?'<b class="required">*</b>':''}${f.hideType?'':`<code>${esc(f.type)}</code>`}</span>${control}<small>${esc(f.source==='session'?'Diambil dari akun yang aktif.':f.source==='constant'?'Nilai tetap sesuai kontrak client.':f.description||'')}${f.maxBytes?` · Maksimum ${(f.maxBytes/1024/1024).toFixed(0)} MB`:''}</small></label>`;}
function operation(o){const fields=o.fields||[],complex=fields.some(f=>f.source==='input'&&f.type!=='file'&&(/[.\[\]]/.test(f.path)||['object','array','unknown'].includes(f.type)));const can=ready(o)&&state.connection.configured&&(!needsAuth(o)||state.authenticated);const reason=!ready(o)?o.reason:!state.connection.configured?state.connection.reason:needsAuth(o)&&!state.authenticated?'Masuk ke akun untuk menguji layanan ini.':'';const point=state.points.find(p=>p.id===state.selectedPoint);return `<button class="back-link" data-action="back">← Kembali ke layanan</button>${head(esc(o.group).toUpperCase(),esc(o.label),'Lengkapi parameter, tinjau request, lalu jalankan pengujian.',badge(status(o),ready(o)?'success':'warning'))}<div class="operation-layout"><section class="panel"><div class="section-heading"><h2>Data permintaan</h2>${badge(write(o)?'Pengiriman data':'Pembacaan data',write(o)?'warning':'neutral')}</div>${reason?notice(esc(reason)):''}<form id="operation-form" data-id="${esc(o.id)}" data-complex="${complex}">${complex?`<label>Data parameter (JSON)<textarea class="json-editor" name="__json" rows="12" spellcheck="false" placeholder="{}">{}</textarea><small>Gunakan nama field sesuai kontrak di bawah. Nilai tidak diisi otomatis.</small></label>`:`<div class="parameter-grid">${fields.filter(f=>f.type!=='file').map(field).join('')}</div>`}${fields.filter(f=>f.type==='file').map((f,i)=>field(f,500+i)).join('')}${!fields.length?'<p class="muted">Tidak ada parameter eksplisit yang perlu diisi.</p>':''}<div id="operation-error" class="inline-error" role="alert"></div><div class="form-actions"><span>${icon('shield',15)} Periksa parameter sebelum menjalankan.</span><button class="button" type="submit" ${can?'':'disabled'}>Tinjau permintaan ${icon('arrow',16)}</button></div></form><details class="contract-details" ${!ready(o)?'open':''}><summary>${icon('code',17)} Parameter & detail teknis</summary><div class="endpoint-row">${badge(o.method)}<code>${esc(o.endpoint)}</code></div><div class="table-scroll"><table><thead><tr><th>Field</th><th>Tipe client</th><th>Wajib server</th></tr></thead><tbody>${fields.map(f=>`<tr><td><code>${esc(f.path)}</code></td><td>${esc(f.type)}</td><td>${f.required==='unknown'?'Belum diketahui':esc(f.required)}</td></tr>`).join('')}</tbody></table></div><p>${esc(o.coordinateNotice||'Struktur berasal dari audit client. Validasi dan penerimaan server perlu dibuktikan melalui pengujian.')}</p></details></section><aside class="result-side"><section class="panel"><div class="section-heading"><h2>Hasil layanan</h2>${state.results.has(o.id)?badge(`HTTP ${state.results.get(o.id).status}`,'success'):badge('Belum dijalankan')}</div>${state.results.has(o.id)?result(state.results.get(o.id)):empty('Menunggu pengujian','Respons server tampil setelah Anda menjalankan permintaan.','wifi')}</section><div class="small-note">${icon('info',17)}<p>Hasil hanya berasal dari request yang Anda jalankan. Data akun tidak diisi dengan contoh.</p></div></aside></div>`;}
function result(r){const envelope=redact(r.data);const data=envelope&&typeof envelope==='object'&&!Array.isArray(envelope)&&Object.hasOwn(envelope,'data')?envelope.data:envelope;const rows=dataItems(data)||dataItems(data?.data);let output='';if(Array.isArray(rows)&&rows.length===0)output='<p class="result-text">Server mengembalikan daftar kosong.</p>';else if(rows?.length&&rows.slice(0,30).every(row=>row&&typeof row==='object'&&!Array.isArray(row))){const keys=[...new Set(rows.slice(0,30).flatMap(x=>Object.keys(x)))].slice(0,5);output=`<p class="result-count">${rows.length} item dalam respons</p><div class="table-scroll"><table><thead><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,30).map(row=>`<tr>${keys.map(k=>`<td>${esc(typeof row[k]==='object'?JSON.stringify(row[k]):row[k]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}else if(data&&typeof data==='object'&&!Array.isArray(data))output=`<dl class="response-facts">${Object.entries(data).filter(([,v])=>v===null||typeof v!=='object').slice(0,10).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v??'—')}</dd></div>`).join('')}</dl>`;if(!output)output=`<p class="result-text">${esc(typeof data==='string'?data.slice(0,1000):Array.isArray(data)&&!data.length?'Server mengembalikan daftar kosong.':'Respons diterima dari server.')}</p>`;const url=typeof r.downloadUrl==='string'&&/^\/api\/downloads?\/[a-zA-Z0-9_-]+$/.test(r.downloadUrl)?r.downloadUrl:null;return `${output}${url?`<a class="button secondary" href="${esc(url)}" download>${icon('download',16)} Unduh lampiran</a>`:''}<details class="json-details"><summary>Lihat respons JSON</summary><pre>${json(envelope)}</pre></details>`;}
function coordinatePreparation(){const tz=Intl.DateTimeFormat().resolvedOptions().timeZone;return `${head('DATA PENGUKURAN','Titik referensi dan pengukuran','Gunakan titik dari GNSS eksternal atau hasil pengukuran Anda.',`<button class="button secondary" data-action="export-points" ${state.points.length?'':'disabled'}>${icon('download',17)} Ekspor titik</button>`)}<div class="coordinate-layout"><section class="panel"><div class="section-heading"><h2>Tambahkan titik ukur</h2>${badge('WGS 84 · EPSG:4326')}</div><form id="point-form"><label>Nama titik<input name="name" required maxlength="100" placeholder="Patok A / titik pengambilan foto"></label><div class="form-row"><label>Lintang (latitude)<input name="latitude" type="number" step="any" min="-90" max="90" placeholder="Derajat desimal" required></label><label>Bujur (longitude)<input name="longitude" type="number" step="any" min="-180" max="180" placeholder="Derajat desimal" required></label></div><label>Sumber koordinat<select name="source"><option value="survey">Hasil pengukuran</option><option value="external_gnss">GNSS eksternal</option></select></label><div class="form-row"><label>Waktu pengukuran<input name="measuredAt" type="datetime-local"><small class="field-hint">Zona waktu komputer: ${esc(tz)}</small></label><label>Akurasi horizontal (meter)<input name="accuracy" type="number" min="0" step="any" placeholder="Opsional"></label></div><label>Referensi pengukuran<input name="note" maxlength="300" placeholder="Perangkat, nomor titik, atau catatan ukur"></label><div id="point-error" class="inline-error" role="alert"></div><button type="submit" class="button full">${icon('plus',17)} Simpan titik untuk sesi ini</button><p class="form-hint">Gunakan derajat desimal WGS 84. Titik belum dikirim ke server.</p></form></section><div class="coordinate-secondary"><section class="panel import-panel"><span class="square-icon mint">${icon('upload',23)}</span><h2>Impor hasil pengukuran</h2><p>Impor GeoJSON, CSV, atau rekaman NMEA dari alat GNSS.</p><label class="file-drop">${icon('upload',26)}<strong>Pilih file koordinat</strong><span>.geojson · .json · .csv · .nmea · .txt</span><input id="point-file" type="file" accept=".geojson,.json,.csv,.nmea,.nme,.txt,.log"></label><button class="text-button template-link" data-action="csv-template">Unduh template CSV ${icon('download',14)}</button><p class="form-hint">Maksimum 2 MB. Format dan koordinat divalidasi sebelum impor.</p><div id="import-error" class="inline-error" role="alert"></div></section><section class="panel coordinate-context"><span class="eyebrow">PEMERIKSAAN LOKAL</span><h3>Satu titik, sumber yang jelas.</h3><p>Titik pengukuran dan koordinat referensi dibandingkan tanpa mengubah posisi perangkat atau mengirimkannya ke layanan.</p><div class="small-note">${icon('info',17)}<p>Sumber, waktu, dan akurasi tetap menjadi metadata lokal. Field ini tidak ditambahkan ke request yang tidak mendukungnya.</p></div></section></div></div><section class="panel points-panel"><div class="section-heading"><div><h2>Titik pengukuran sesi ini</h2><p>Pilih titik sebagai pengukuran untuk perbandingan lokal.</p></div>${badge(`${state.points.length} titik`)}</div>${state.points.length?`<div class="point-list">${state.points.map(p=>`<button class="point-row ${p.id===state.selectedPoint?'selected':''}" data-action="select-point" data-id="${esc(p.id)}"><span class="point-radio">${p.id===state.selectedPoint?icon('check',14):''}</span><span class="point-main"><strong>${esc(p.name||'Titik pengukuran')}</strong><small>${p.latitude.toFixed(7)}, ${p.longitude.toFixed(7)}</small><span class="point-time">${p.measuredAt?esc(new Date(p.measuredAt).toLocaleString('id-ID')):'Waktu ukur tidak dicantumkan'}</span></span><span class="point-source">${({external_gnss:'GNSS eksternal',survey:'Hasil pengukuran',browser:'Lokasi browser'})[p.source]||'Sumber tidak dikenal'}<small>${p.accuracy===null?'Akurasi tidak dicantumkan':`Akurasi ${esc(p.accuracy)} m`}</small></span><span class="point-selected">${p.id===state.selectedPoint?'Terpilih':'Pilih titik'}</span></button>${p.warnings?.length?`<p class="point-warning">${esc(p.warnings.join(' '))}</p>`:''}`).join('')}</div>`:empty('Belum ada titik pengukuran','Tambahkan titik secara manual atau impor hasil pengukuran.','pin')}</section>`;}
function activity(items){return `<div class="activity-list">${items.map(a=>`<div class="activity-item"><span class="activity-indicator ${a.outcome}">${icon(a.outcome==='success'?'check':a.outcome==='error'?'warning':'clock',16)}</span><div><strong>${esc(a.label)}</strong><p>${esc(a.detail)}</p></div><time datetime="${esc(a.time)}">${new Date(a.time).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}</time></div>`).join('')}</div>`;}
function testing(){return `<div class="advanced-entry"><a class="button secondary" href="#/catalog">${icon('code',17)} Katalog kontrak API</a><p>Detail kontrak dan parameter tersedia untuk pemeriksaan lanjutan.</p></div>${head('VALIDASI & RESPONS','Pengujian layanan','Periksa kesiapan lokal dan hasil nyata dari request pada sesi ini.',`<button class="button secondary" data-action="self-check">${icon('refresh',17)} Jalankan pemeriksaan lokal</button>`)}<div class="testing-metrics">${[['Request pada sesi ini',state.activity.length],['Respons berhasil',state.activity.filter(a=>a.outcome==='success').length],['Gagal / ditolak',state.activity.filter(a=>a.outcome==='error').length]].map(([a,b])=>`<section class="panel"><span class="metric-label">${a}</span><strong class="metric-value">${b}</strong></section>`).join('')}</div><section class="panel checks-panel"><div class="section-heading"><div><h2>Kesiapan workspace</h2><p>Pemeriksaan hanya menghubungi server lokal di komputer ini.</p></div>${badge('LOKAL')}</div>${state.checks.length?`<div class="check-list">${state.checks.map(c=>`<div class="check-row">${icon(c.ok?'check':'warning',17)}<strong>${esc(c.label)}</strong><span>${esc(c.detail)}</span>${badge(c.ok?'Lulus':'Perlu tindakan',c.ok?'success':'warning')}</div>`).join('')}</div>`:empty('Pemeriksaan belum dijalankan','Gunakan tombol di atas untuk memeriksa server, katalog, dan konfigurasi.','shield')}</section><section class="panel"><div class="section-heading"><div><h2>Riwayat sesi</h2><p>Tanpa kata sandi, token, atau salinan dokumen.</p></div><button class="button secondary small" data-action="export-activity" ${state.activity.length?'':'disabled'}>${icon('download',15)} Ekspor log</button></div>${state.activity.length?activity(state.activity):empty('Pengujian belum dijalankan','Masuk ke akun, pilih layanan, lalu tinjau dan jalankan request.','flask')}</section><div class="diagnostic-grid"><section class="panel"><h2>Cakupan browser</h2><dl class="detail-list">${[['Versi sumber APK',state.version],['Operasi dalam katalog',state.operations.length],['Struktur dapat diuji',state.operations.filter(ready).length],['Login khusus',state.operations.filter(login).length],['Perlu pemetaan',state.operations.filter(o=>!ready(o)&&!login(o)).length]].map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl></section><section class="panel"><h2>Status integrasi</h2><p>Kesetaraan penuh dengan Android belum terverifikasi. Integritas client dan fungsi native dapat memengaruhi penerimaan server.</p><details class="json-details"><summary>Detail kapabilitas</summary><pre>${json(state.capabilities)}</pre></details><a class="text-link" href="#/services">Pilih layanan untuk diuji ${icon('arrow',15)}</a></section></div>`;}
function connectionPage(){return `${head('SESI & KONEKSI','Akun Anda','Hubungkan akun untuk mengakses layanan yang memerlukan autentikasi.')}<div class="account-layout">${loginCard()}<div class="account-details"><section class="panel"><div class="section-heading"><h2>Koneksi layanan</h2>${badge(state.connection.configured?'Dikonfigurasi':'Perlu konfigurasi',state.connection.configured?'success':'warning')}</div><dl class="detail-list">${[['Tujuan backend',state.connection.origin||'Belum dikonfigurasi'],['Versi client sumber',state.version],['Status akun',state.authenticated?'Terautentikasi':'Belum masuk']].map(([a,b])=>`<div><dt>${a}</dt><dd>${esc(b)}</dd></div>`).join('')}</dl>${state.connection.reason?notice(esc(state.connection.reason)):''}<button class="button secondary" data-action="refresh">${icon('refresh',17)} Periksa ulang</button></section><section class="panel privacy-panel"><span class="square-icon">${icon('shield')}</span><h2>Sesi dikelola di komputer ini</h2><p>Kata sandi digunakan saat login dan tidak disimpan oleh workspace. Token dikelola layanan lokal tanpa ditampilkan ke browser.</p><p>Koordinat dan riwayat pengujian berada dalam memori tab. Ekspor hasil yang diperlukan sebelum memuat ulang, keluar akun, atau menutup halaman.</p><div class="local-client-label">Klien browser tidak resmi untuk pengujian. Belum semua alur Android tersedia.</div></section></div></div>`;}
function render(){shell();const op=state.operations.find(o=>o.id===selected);const views={dashboard,services:serviceDirectory,catalog:()=>catalog(),coordinates:coordinatePage,testing,account,...Object.fromEntries(Object.keys(flowDefinitions).map(key=>[key,flowPage]))};$('#main').innerHTML=`${state.loadError?notice(`${esc(state.loadError)} <button class="text-button" data-action="refresh">Coba lagi</button>`,'error'):''}${op?operation(op):(views[route]||(externalPages[route]?externalPage:profileMenus.some(m=>m.route===route)?profileSection:unavailablePage))()}`;document.title=`${op?op.label:routes[route]} · Sentuh Tanahku Workspace`;berkasBookmarkPaint();}
function navigate(){flowResults.delete('activity:delete-state');resetCollectionNavigation();resetNewsNavigation();const queue=flowResults.get('queue:default');if(queue){queue.request=null;queue.loading=false;queue.scheduled=false;queue.attempted=false;queue.detail=null;if(queue.calls){queue.calls.request=null;queue.calls.loading=false;queue.calls.scheduled=false;queue.calls.attempted=false;}}const office=flowResults.get('office:nearby');if(office){office.request=null;office.locationBusy=false;office.loading=false;office.detailOpen=false;office.calendar.request=null;office.calendar.loading=false;office.calendar.scheduled=false;}flowResults.delete('information:default');resetSearchFileNavigation();resetPartnerNavigation();const name=location.hash.replace(/^#\/?/,'').split('?')[0];route=name==='login'?'account':name==='documents'?'certificates':Object.hasOwn(routes,name)?name:'dashboard';selected=route==='catalog'?new URLSearchParams(location.hash.split('?')[1]||'').get('operation'):null;flowTab='';flowDetail=null;htDetailData=null;flowQuery='';flowPageIndex=0;detailSequence++;search='';group='Semua';filter='Semua';$('#modal').close();pending=null;document.body.classList.remove('menu-open');render();window.scrollTo(0,0);}
function download(name,value,type='application/json'){const url=URL.createObjectURL(new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function showReview(form,op){let values={},files=[];if(form.dataset.complex==='true'){try{values=JSON.parse(form.elements.__json.value);}catch{throw new Error('Parameter JSON belum valid.');}if(!values||typeof values!=='object'||Array.isArray(values))throw new Error('Parameter harus berupa objek JSON.');}for(const f of op.fields){if(f.source!=='input')continue;const input=form.elements.namedItem(f.path);if(!input)continue;if(f.type==='file'){if(input.files?.length){const file=input.files[0];if(f.maxBytes&&file.size>f.maxBytes)throw new Error(`Ukuran ${f.label||f.path} melebihi ${(f.maxBytes/1024/1024).toFixed(0)} MB.`);files.push({key:f.path,file});}continue;}if(form.dataset.complex==='true'||input.value==='')continue;if(f.type==='boolean')values[f.path]=input.value==='true';else if(['number','integer'].includes(f.type)){const n=Number(input.value);if(!Number.isFinite(n)||(f.type==='integer'&&!Number.isInteger(n)))throw new Error(`Nilai ${f.path} harus berupa angka${f.type==='integer'?' bulat':''}.`);values[f.path]=n;}else values[f.path]=input.value;}pending={op,values,files};$('#modal').innerHTML=`<div class="modal-heading"><div><div class="eyebrow">PERIKSA SEBELUM MELANJUTKAN</div><h2 id="modal-title">Tinjau permintaan Anda</h2></div><button class="icon-button" data-action="modal-close" aria-label="Tutup dialog">${icon('close')}</button></div><div class="modal-body"><p class="review-intro">${esc(op.label)}</p><div class="review-destination">${icon('wifi',19)}<div><small>Tujuan layanan</small><strong>${esc(state.connection.origin||'Backend yang dikonfigurasi')}</strong></div>${badge(op.method)}</div>${write(op)?notice('Operasi ini dapat mengubah data pada layanan tujuan. Periksa seluruh nilai sebelum mengirim.','warning'):''}<details class="json-details" open><summary>Parameter yang Anda isi</summary><pre>${json(values)}</pre></details>${op.fields.some(f=>f.source!=='input')?`<p class="form-hint">Field dari sesi atau konstanta ditambahkan oleh layanan lokal: ${esc(op.fields.filter(f=>f.source!=='input').map(f=>f.path).join(', '))}.</p>`:''}${files.length?`<div class="review-files">${files.map(({key,file})=>`<div>${icon('document',16)}<span><strong>${esc(file.name)}</strong><small>${esc(key)} · ${(file.size/1024).toFixed(1)} KB</small></span></div>`).join('')}</div>`:''}<p class="form-hint">Nilai sensitif disembunyikan dari tinjauan. Nilai asli digunakan pada request.</p><div id="review-error" class="inline-error" role="alert"></div><div class="modal-actions"><button class="button secondary" data-action="modal-close">Kembali & periksa</button><button class="button" data-action="execute">${write(op)?'Kirim ke server':'Jalankan permintaan'} ${icon('arrow',16)}</button></div></div>`;$('#modal').showModal();}
async function execute(button){if(!pending||busy)return;busy=true;const request=pending,requestEpoch=sessionEpoch;button.disabled=true;button.textContent='Mengirim permintaan…';const {op,values,files}=request,profileKey=op.endpoint==='account/account_summary'?'accountsummary:default':null,profileRequest=profileKey?{loading:true}:null,profileCurrent=()=>!profileKey||flowResults.get(profileKey)===profileRequest;if(profileKey)flowResults.set(profileKey,profileRequest);let body={operationId:op.id,values,...(write(op)?{confirm:true}:{})};if(files.length){body=new FormData();body.append('operationId',op.id);body.append('values',JSON.stringify(values));if(write(op))body.append('confirm','true');for(const f of files)body.append(f.key,f.file);}try{const data=await api('/api/execute',{method:'POST',body});if(requestEpoch!==sessionEpoch||!profileCurrent())return;if(profileKey&&!nativeAccountSummary(data.result))throw new Error('Respons profil belum dikenali. Coba muat profil kembali.');state.results.set(op.id,data.result);if(profileKey){Object.assign(profileRequest,{response:data.result,loading:false});state.profileError='';}record(op.label,'success',`HTTP ${data.result?.status||200} · Respons diterima`);if(pending!==request)return;pending=null;$('#modal').close();render();toast('Respons layanan diterima.');}catch(e){if(requestEpoch!==sessionEpoch||!profileCurrent())return;if(profileKey){Object.assign(profileRequest,{error:e.message,loading:false});state.results.delete(op.id);state.profileError=e.message;}record(op.label,'error',`${e.code||'ERROR'} · ${e.message}`);if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(e.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(e.message);return;}if(pending!==request)return;const target=$('#review-error');if(target)target.textContent=e.message;else toast(e.message);button.disabled=false;button.textContent='Coba kirim lagi';}finally{busy=false;}}
async function selfCheck(button){button.disabled=true;button.textContent='Memeriksa lokal…';try{const data=await api('/api/diagnostics');state.checks=(data.checks||[]).map(c=>({label:c.name,ok:c.passed,detail:c.detail}));}catch(e){state.checks=[{label:'Diagnostik lokal',ok:false,detail:e.message}];}render();toast('Pemeriksaan lokal selesai. Tidak ada request ke backend resmi.');}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;if(action==='skip'){e.preventDefault();$('#main').focus();}else if(action==='menu'){b.setAttribute('aria-expanded',String(document.body.classList.toggle('menu-open')));}else if(action==='menu-close')document.body.classList.remove('menu-open');else if(action==='refresh')await load();else if(action==='password'){const input=$('#password');input.type=input.type==='password'?'text':'password';b.setAttribute('aria-label',input.type==='password'?'Tampilkan kata sandi':'Sembunyikan kata sandi');}else if(action==='operation'){const op=state.operations.find(o=>o.id===id);if(login(op)){location.hash='/account';return;}selected=id;render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});}else if(action==='back'){selected=null;render();}else if(action==='modal-close'&&!busy){pending=null;htDetailData=null;$('#modal').close();}else if(action==='execute')await execute(b);else if(action==='logout'){if(logoutPending)return;logoutPending=true;b.disabled=true;const logoutEpoch=++sessionEpoch;state.authenticated=false;state.user=null;clearPrivate();render();try{const data=await api('/api/logout',{method:'POST',body:{}});if(logoutEpoch!==sessionEpoch)return;session(data);clearPrivate();render();toast('Anda sudah keluar. Data sesi browser dibersihkan.');}catch(error){if(logoutEpoch!==sessionEpoch)return;toast(error.message);}finally{logoutPending=false;if(logoutEpoch===sessionEpoch){const loginButton=$('#login-form button[type=submit]');if(loginButton)loginButton.disabled=!state.connection.configured||state.loading||authPending;}}}else if(action==='select-point'){state.selectedPoint=id;comparisonSelection.measured=id;render();toast('Titik dipilih untuk pemeriksaan lokal.');}else if(action==='export-points')download('koordinat-pengukuran.geojson',toGeoJSON(state.points),'application/geo+json');else if(action==='csv-template')download('template-koordinat.csv','latitude,longitude,name,source,accuracy_m,measured_at,crs\r\n','text/csv');else if(action==='export-activity')download('hasil-pengujian-sesi.json',{exportedAt:new Date().toISOString(),version:state.version,activity:state.activity});else if(action==='self-check')await selfCheck(b);});
document.addEventListener('submit',async e=>{const form=e.target;if(!['login-form','operation-form','point-form'].includes(form.id))return;e.preventDefault();if(form.id==='login-form'){if(authPending||logoutPending)return;const signinAttempt=++authSequence;const loginEpoch=sessionEpoch;const b=$('button[type=submit]',form),username=form.elements.username.value.trim(),password=form.elements.password.value;if(!username||!password)return;authPending=true;b.disabled=true;b.textContent='Menghubungkan akun…';$('#login-error').textContent='';try{const data=await api('/api/login',{method:'POST',body:{username,password}});form.elements.password.value='';if(loginEpoch!==sessionEpoch)return;sessionEpoch++;clearPrivate();session(data);record('Masuk akun','success','Autentikasi diterima oleh layanan');const connectedEpoch=sessionEpoch;authPending=false;render();toast('Akun berhasil terhubung.');await refreshNativeProfile();if(connectedEpoch===sessionEpoch)render();}catch(error){form.elements.password.value='';if(loginEpoch!==sessionEpoch)return;const target=$('#login-error');if(target)target.textContent=error.message;else toast(error.message);record('Masuk akun','error',`${error.code||'ERROR'} · ${error.message}`);b.disabled=false;b.textContent='Masuk & hubungkan';}finally{if(signinAttempt===authSequence){authPending=false;const current=$('#login-form button[type=submit]');if(current){current.disabled=!state.connection.configured||state.loading||logoutPending;current.innerHTML=`Masuk & hubungkan ${icon('arrow',16)}`;}}}}else if(form.id==='operation-form'){try{showReview(form,state.operations.find(o=>o.id===form.dataset.id));}catch(error){$('#operation-error').textContent=error.message;}}else{try{if(state.points.length>=500)throw new Error('Maksimum 500 titik per sesi.');const values=Object.fromEntries(new FormData(form));const point=normalizePoint({...values,crs:'EPSG:4326',accuracy:values.accuracy===''?null:values.accuracy,measuredAt:values.measuredAt?new Date(values.measuredAt).toISOString():null});state.points.push(point);state.selectedPoint=point.id;render();toast('Titik pengukuran ditambahkan.');}catch(error){$('#point-error').textContent=error.message;}}});
document.addEventListener('input',e=>{if(e.target.id==='catalog-search'){search=e.target.value;render();const input=$('#catalog-search');input.focus();input.setSelectionRange(search.length,search.length);}else if(e.target.closest('#information-simulation-form'))updateInformationSimulationInput(e.target);else if(e.target.id==='searchfile-office-query')filterSearchFileOffices(e.target);else if(e.target.closest('#searchfile-form'))updateSearchFileInput(e.target);else if(e.target.id==='ht-search')filterHtDetail(e.target);else if(e.target.id==='flow-search')filterFlow(e.target);});
document.addEventListener('change',async e=>{if(e.target.closest('#information-simulation-form'))updateInformationSimulationInput(e.target);else if(e.target.closest('#searchfile-form')){updateSearchFileInput(e.target);}else if(e.target.id==='activity-filter'){filterActivity(e.target.value);}else if(e.target.id==='group-filter'){group=e.target.value;render();}else if(e.target.id==='status-filter'){filter=e.target.value;render();}else if(e.target.id==='point-file'){const file=e.target.files[0];if(!file)return;const importEpoch=sessionEpoch;try{if(file.size>2*1024*1024)throw new Error('Ukuran file maksimum 2 MB.');const extension=file.name.split('.').pop().toLowerCase();const text=await file.text();if(importEpoch!==sessionEpoch)return;const points=parseCoordinateFile(text,extension).map(point=>({...point,sourceId:point.id,id:crypto.randomUUID()}));if(state.points.length+points.length>500)throw new Error('Maksimum 500 titik per sesi.');state.points.push(...points);if(!state.selectedPoint)state.selectedPoint=points[0]?.id;render();toast(`${points.length} titik berhasil diimpor.`);}catch(error){if(importEpoch!==sessionEpoch)return;const target=$('#import-error');if(target)target.textContent=error.message;else toast(error.message);}}});
$('#modal').addEventListener('cancel',e=>{if(busy||collectionGroupCreate?.busy||collectionItemEdit?.busy)e.preventDefault();else{collectionGroupCreate=null;collectionGroupMove=null;collectionGroupDelete=null;collectionGroupRemove=null;collectionItemDelete=null;collectionItemEdit=null;if(!flowResults.get('activity:delete-state')?.busy&&flowResults.delete('activity:delete-state'))render();pending=null;htDetailData=null;}});
$('#modal').addEventListener('close',()=>{if(!$('#modal').open){collectionGroupCreate=null;collectionGroupMove=null;collectionGroupDelete=null;collectionGroupRemove=null;collectionItemDelete=null;collectionItemEdit=null;if(!flowResults.get('activity:delete-state')?.busy&&flowResults.delete('activity:delete-state'))render();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('menu-open');});
window.addEventListener('hashchange',navigate);navigate();load();
function shell(){const nav=visibleNativeMenus();const navAsset=r=>({dashboard:'home',collections:'bookmark',scan:'scan',activity:'activity',account:'user'})[r];const extra=[['services','Layanan','grid'],['coordinates','Perbandingan Koordinat','pin'],['testing','Pengujian Lanjutan','flask']];$('#app').innerHTML=`<aside class="sidebar official-sidebar" aria-label="Navigasi utama"><a class="brand" href="#/dashboard"><img src="assets/logo-bpn.png" alt=""><span>Sentuh Tanahku<small>VERSI BROWSER · TIDAK RESMI</small></span></a><div class="sidebar-greeting"><span>${state.authenticated?'Selamat datang,':'Halo, Sobat ATR/BPN'}</span><strong>${esc(state.user?.username||'Masuk untuk melihat data Anda')}</strong></div><nav>${nav.map(([r,t,i])=>`<a class="nav-item ${route===r?'active':''}" href="#/${r}" ${route===r?'aria-current="page"':''}><img class="native-nav-icon" width="21" height="21" src="assets/icons/nav-${navAsset(r)}.png" alt=""><span>${t}</span></a>`).join('')}</nav><div class="nav-divider"></div><div class="nav-label">LAYANAN & ALAT</div><nav>${extra.map(([r,t,i])=>`<a class="nav-item ${route===r||r==='testing'&&route==='catalog'?'active':''}" href="#/${r}">${icon(i)}<span>${t}</span></a>`).join('')}</nav><div class="sidebar-bottom"><div class="source-status"><span class="tiny-dot"></span> Berdasarkan APK ${esc(state.version)}<small>Tampilan browser disesuaikan dengan perangkat.</small></div></div></aside><button class="menu-overlay" data-action="menu-close" aria-label="Tutup navigasi"></button><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" data-action="menu" aria-label="Buka navigasi" aria-expanded="false">${icon('menu')}</button><span>Sentuh Tanahku</span>${icon('chevron',14)}<strong>${routes[route]||'Layanan'}</strong></div><div class="topbar-right"><span class="connection-pill ${state.authenticated?'connected':''}"><span class="tiny-dot"></span>${state.loading?'Memeriksa sesi…':state.authenticated?'Akun terhubung':state.connection.configured?'Belum masuk':'Koneksi belum siap'}</span><a class="avatar" href="#/account" aria-label="Buka akun">${icon('user',17)}</a></div></header><main id="main" tabindex="-1"></main><footer class="footer"><span>Sentuh Tanahku · Klien browser tidak resmi</span><span>Nama menu dan ikon dari APK · Kesetaraan penuh belum terverifikasi</span></footer></div><nav class="bottom-navigation nav-count-${nav.length}" aria-label="Navigasi ponsel">${nav.map(([r,t,i])=>`<a href="#/${r}" class="${route===r?'active':''} ${r==='scan'?'scan-tab':''}" ${route===r?'aria-current="page"':''}><img class="native-nav-icon" width="21" height="21" src="assets/icons/nav-${navAsset(r)}.png" alt=""><span>${t}</span></a>`).join('')}</nav>`;}
function menuTiles(){return serviceMenus.map(m=>`<a class="official-menu-tile" href="#/${m.route}"><span><img src="assets/icons/${esc(m.asset)}" alt=""></span><strong>${esc(m.label)}</strong></a>`).join('');}
function dashboard(){return `<div class="home-heading"><div><span class="eyebrow">SENTUH TANAHKU</span><h1>${state.authenticated?`Halo, ${esc(state.user?.username||'Sobat ATR/BPN')}.`:'Halo, Sobat ATR/BPN.'}</h1><p>Akses informasi pertanahan dan layanan Anda.</p></div>${state.authenticated?badge('Akun terhubung','success'):`<a class="button" href="#/account">${icon('user',16)} Masuk</a>`}</div><div class="home-layout"><div><section class="official-welcome"><div><span class="hero-eyebrow">KEMENTERIAN AGRARIA DAN TATA RUANG / BPN</span><h2>Informasi pertanahan<br>dalam genggaman Anda.</h2><p>${state.authenticated?'Lihat sertipikat, pantau berkas, dan akses informasi layanan dari akun Anda.':'Masuk untuk melihat sertipikat, berkas, dan aktivitas yang terhubung dengan akun Anda.'}</p><a class="button white" href="#/${state.authenticated?'certificates':'account'}">${state.authenticated?'Buka Sertipikatku':'Masuk ke akun'} ${icon('arrow',16)}</a></div><div class="welcome-emblem"><img src="assets/logo-bpn.png" alt="Lambang ATR/BPN"></div></section><section class="panel laci-panel"><div class="section-heading"><h2>Laci</h2><span class="subtle">Dokumen & berkas Anda</span></div><div class="laci-grid">${[['certificates','Sertipikatku','sertipikatku.svg'],['akta','Aktaku','akta.svg'],['files','Berkasku','berkasku.svg']].map(([r,t,a])=>`<a href="#/${r}"><img src="assets/icons/${a}" alt=""><strong>${t}</strong>${!state.authenticated?icon('lock',12):''}</a>`).join('')}</div></section><section class="panel official-services"><div class="section-heading"><h2>Layanan Pertanahan</h2><a class="text-link" href="#/services">Lihat semua ${icon('arrow',14)}</a></div><div class="official-menu-grid">${menuTiles()}</div></section></div><aside class="home-aside"><section class="panel favorite-office"><span class="square-icon mint">${icon('pin',22)}</span><h2>Kantor Pertanahan</h2><p>Cari kantor pertanahan untuk informasi layanan Anda.</p><a class="button secondary full" href="#/office">Cari kantor ${icon('search',16)}</a></section><section class="panel home-news"><div class="section-heading"><h2>Informasi</h2></div>${informationMenus.map(m=>`<a href="#/${m.route}"><img src="assets/icons/${m.asset}" alt=""><span><strong>${m.label}</strong></span>${icon('chevron',16)}</a>`).join('')}</section><section class="comparison-promo"><span>${icon('pin',22)}</span><div><h3>Periksa selisih koordinat</h3><p>Bandingkan titik referensi dengan hasil pengukuran secara lokal.</p><a href="#/coordinates" class="text-link">Buka perbandingan ${icon('arrow',14)}</a></div></section></aside></div>${newsFeedSection('news')}${newsFeedSection('announcements')}<div class="reconstruction-note">${icon('info',15)}<span>Nama menu dan aset mengikuti APK. Susunan layar browser disesuaikan; kesetaraan visual dan seluruh alur Android belum terverifikasi.</span></div>`;}
function serviceDirectory(){return `${head('LAYANAN PERTANAHAN','Layanan Sentuh Tanahku','Pilih layanan yang ingin Anda gunakan.')}<div class="service-directory">${serviceMenus.map(m=>`<a href="#/${m.route}" class="service-directory-card"><img src="assets/icons/${esc(m.asset)}" alt=""><div><h2>${esc(m.label)}</h2><p>${esc(m.description)}</p></div>${icon('chevron',19)}</a>`).join('')}</div><div class="secondary-services">${[['collections','Koleksi','files.svg'],['office','Kantor Pertanahan','company.svg'],['news','Berita','newspaper.svg']].map(([r,t,a])=>`<a class="document-shortcut" href="#/${r}"><img src="assets/icons/${a}" alt=""><div><strong>${t}</strong><span>Buka layanan</span></div>${icon('chevron',16)}</a>`).join('')}</div>`;}
function currentFlow(){const def=flowDefinitions[route];if(!def)return null;if(route==='partners')return partnerFlowContext(def);const tab=def.tabs?(def.tabs.find(t=>t.id===flowTab)||def.tabs[0]):def;return {def,tab,key:`${route}:${tab.id||'default'}`,op:state.operations.find(o=>o.endpoint===tab.endpoint&&ready(o))||state.operations.find(o=>o.endpoint===tab.endpoint)};}
function nativeVerificationStatus(response){const body=response?.data;if(!Number.isInteger(response?.status)||response.status<200||response.status>=300||!body||typeof body!=='object'||Array.isArray(body))return null;if(body.error!=null&&typeof body.error!=='boolean'||body.message!=null&&typeof body.message!=='string'||body.data!=null&&typeof body.data!=='string')return null;return {error:body.error??null,message:body.message??null,data:body.data??null};}
function nativeOfficeEnvelope(response,valid){const body=response?.data;if(!Number.isInteger(response?.status)||response.status<200||response.status>=300||!body||typeof body!=='object'||Array.isArray(body)||typeof body.error!=='boolean'||body.message!=null&&typeof body.message!=='string')return null;for(const key of ['totalRecords','resultsCount','pageSize','pageNumber'])if(body[key]!=null&&!Number.isInteger(body[key]))return null;const rows=body.data??[];if(!Array.isArray(rows)||!rows.every(valid))return null;return body.error?[]:rows;}
function nearbyOfficeItem(item){return !!item&&typeof item==='object'&&!Array.isArray(item)&&['kantorId','namaKantor','alamat'].every(key=>typeof item[key]==='string')&&['latitude','longitude','jarak'].every(key=>typeof item[key]==='number'&&Number.isFinite(item[key]))&&['statusAntrian','statusPeralihanEl','statusKiosk'].every(key=>Number.isInteger(item[key]));}
function nearbyOfficeRows(response){return nativeOfficeEnvelope(response,nearbyOfficeItem);}
function officeCalendarItem(item){return !!item&&typeof item==='object'&&!Array.isArray(item)&&['tanggal','keterangan','tipe','tipeLiburId'].every(key=>item[key]==null||typeof item[key]==='string');}
function officeCalendarRows(response){return nativeOfficeEnvelope(response,officeCalendarItem);}
function officeEntries(owner){const query=owner.query.toLowerCase(),filters=[[1,'statusPeralihanEl'],[2,'statusAntrian'],[3,'statusKiosk']];return (owner.rows||[]).map((item,index)=>({item,index})).filter(({item})=>item.namaKantor.toLowerCase().includes(query)&&filters.every(([id,key])=>!owner.filters.includes(id)||item[key]===1));}
function getOfficeState(){let owner=flowResults.get('office:nearby');if(!owner){const now=new Date();owner={rows:null,query:'',filters:[],position:null,locationBusy:false,loading:false,error:'',request:null,selected:null,detailOpen:false,calendar:{year:now.getFullYear(),month:now.getMonth(),rows:null,loading:false,error:'',request:null,office:null,loadedYear:null}};flowResults.set('office:nearby',owner);}return owner;}
function officeFiltersView(owner){return `<div class="office-filters" role="group" aria-label="Fasilitas kantor">${[[1,'Peralihan Elektronik'],[2,'Antrian Daring'],[3,'Anjungan Pencetakan Sertipikat']].map(([id,label])=>`<button type="button" class="button secondary small ${owner.filters.includes(id)?'selected':''}" data-action="office-filter" data-index="${id}" aria-pressed="${owner.filters.includes(id)}">${label}</button>`).join('')}</div>`;}
function officeFeaturesView(item){return `<ul class="office-features">${[['statusPeralihanEl','Peralihan Elektronik'],['statusAntrian','Antrian Daring'],['statusKiosk','Anjungan Pencetakan Sertipikat']].map(([key,label])=>`<li class="${item[key]===1?'available':'unavailable'}">${icon(item[key]===1?'check':'close',16)}<span>${label}</span><span class="sr-only">${item[key]===1?' tersedia':' belum tersedia'}</span></li>`).join('')}</ul>`;}
