function officeSelectedView(owner){const item=owner.selected;if(!item||!owner.detailOpen)return '';return `<section class="panel office-selected" role="region" aria-label="Kantor yang dipilih"><div class="office-selected-heading"><h2>${esc(item.namaKantor)}</h2><button type="button" class="icon-button" data-action="office-close" aria-label="Tutup informasi kantor">${icon('close')}</button></div>${officeFeaturesView(item)}</section>`;}
function renderOffice(){if(['office','officecalendar'].includes(route))render();}
function officeOperation(endpoint){return state.operations.find(op=>op.endpoint===endpoint&&ready(op)&&!write(op));}
function officeLocationControls(owner){const op=officeOperation('kantornearby/getkantornearby'),busy=owner.locationBusy||owner.loading;return `<section class="panel office-location-controls"><div><h2>Kantor di sekitar lokasi Anda</h2><p>Gunakan lokasi perangkat untuk mencari kantor. Posisi dikirim ke layanan pencarian kantor ATR/BPN.</p></div><button type="button" class="button" data-action="office-location" ${busy||!op||!state.connection.configured?'disabled':''}>${icon('pin',16)} ${owner.locationBusy?'Membaca lokasi…':owner.loading?'Mencari kantor…':owner.rows?'Perbarui lokasi & kantor':'Gunakan lokasi perangkat'}</button>${owner.position&&!busy?'<button type="button" class="text-button" data-action="office-reload">Muat ulang daftar kantor</button>':''}${!op?notice('Pencarian kantor terdekat belum siap pada build ini.'):''}${!state.connection.configured?notice(esc(state.connection.reason||'Koneksi belum siap.')):''}${owner.error?notice(esc(owner.error),'error'):''}</section>`;}
function officePage(){const owner=getOfficeState();return `${head('SENTUH TANAHKU','Kantor Pertanahan','Temukan kantor pertanahan dan fasilitas layanannya.')}${officeLocationControls(owner)}${owner.rows?`${officeSelectedView(owner)}${officeListView(owner)}<p class="form-hint office-map-note">Peta dasar dan kendali Google Maps dari aplikasi Android belum tersedia di browser ini.</p>`:!owner.loading&&!owner.locationBusy?`<section class="panel">${empty('Cari kantor terdekat','Izinkan lokasi perangkat untuk memuat daftar kantor dari layanan.','pin')}</section>`:''}`;}
function officeMonthName(month){return ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'][month]||'';}
function parseOfficeCalendarDate(value){if(typeof value!=='string'||!value)return null;if(value.includes('T')){if(!/^\d{4}-\d{2}-\d{2}T/.test(value))return null;const date=new Date(value);if(!Number.isFinite(date.getTime()))return null;const utc=/(?:Z|[+-]\d{2}(?::?\d{2})?)$/i.test(value);return {year:utc?date.getUTCFullYear():date.getFullYear(),month:utc?date.getUTCMonth():date.getMonth(),day:utc?date.getUTCDate():date.getDate(),time:date.getTime()};}const match=/^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(value);if(!match)return null;const year=Number(match[1]),month=Number(match[2])-1,day=Number(match[3]),date=new Date(0);date.setHours(0,0,0,0);date.setFullYear(year,month,day);if(date.getFullYear()!==year||date.getMonth()!==month||date.getDate()!==day)return null;return {year,month,day,time:date.getTime()};}
function officeCalendarEvents(rows,year,month){return (rows||[]).map((item,index)=>({item,index,date:parseOfficeCalendarDate(item.tanggal)})).filter(entry=>entry.item.tipeLiburId==='2'&&entry.date?.year===year&&entry.date.month===month).sort((a,b)=>a.date.time-b.date.time||a.index-b.index);}
function officeCalendarEventsView(calendar){const entries=officeCalendarEvents(calendar.rows,calendar.year,calendar.month);return `<section class="office-calendar-events">${entries.length?`<ul>${entries.map(({item,date})=>`<li><strong>${date.day} ${officeMonthName(date.month)}</strong><span>${esc(item.keterangan??'Tidak ada keterangan')}</span></li>`).join('')}</ul>`:`<p>${calendar.rows?.length?'Tidak ada data kalender untuk bulan ini':'Tidak ada data kalender tersedia'}</p>`}</section>`;}
function officeCalendarGrid(calendar){const first=new Date(calendar.year,calendar.month,1),offset=(first.getDay()+6)%7,count=new Date(calendar.year,calendar.month+1,0).getDate(),cells=Math.ceil((offset+count)/7)*7,now=new Date(),marked=new Set((calendar.rows||[]).map(item=>parseOfficeCalendarDate(item.tanggal)).filter(date=>date?.year===calendar.year&&date.month===calendar.month).map(date=>date.day));let body='';for(let row=0;row<cells/7;row++){body+='<tr>';for(let column=0;column<7;column++){const date=new Date(calendar.year,calendar.month,row*7+column-offset+1),inside=date.getMonth()===calendar.month,today=date.getFullYear()===now.getFullYear()&&date.getMonth()===now.getMonth()&&date.getDate()===now.getDate();body+=`<td class="${inside?'':'outside'} ${today?'today':inside&&marked.has(date.getDate())?'event-day':''}" ${today?'aria-current="date"':''}><span>${date.getDate()}</span></td>`;}body+='</tr>';}return `<table class="office-calendar-grid" aria-label="Kalender ${officeMonthName(calendar.month)} ${calendar.year}"><thead><tr>${['Sen','Sel','Rab','Kam','Jum','Sab','Mgg'].map((label,index)=>`<th scope="col" class="${index>4?'weekend':''}">${label}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table>`;}
function officeCalendarPage(){const owner=getOfficeState(),calendar=owner.calendar,now=new Date(),op=officeOperation('KantorNearby/GetCalendar');if(calendar.year!==now.getFullYear()||calendar.month<now.getMonth()){Object.assign(calendar,{year:now.getFullYear(),month:now.getMonth(),rows:null,loadedYear:null,request:null,loading:false,error:''});}if(owner.rows?.length&&!owner.selected)owner.selected=owner.rows[0];const usable=owner.selected&&typeof owner.selected.kantorId==='string'&&owner.selected.kantorId.trim(),blocked=!op||!state.connection.configured||op&&needsAuth(op)&&!state.authenticated;if(owner.rows&&usable&&!blocked&&!calendar.loading&&!calendar.error&&!calendar.scheduled&&(calendar.office!==owner.selected||calendar.loadedYear!==calendar.year)){calendar.scheduled=true;queueMicrotask(()=>{calendar.scheduled=false;if(route==='officecalendar'&&flowResults.get('office:nearby')===owner&&owner.calendar===calendar)loadOfficeCalendar();});}return `${head('SENTUH TANAHKU','Kalender Kantor Pertanahan','Kalender Jadwal Pelayanan & Hari Libur')}${officeLocationControls(owner)}${owner.rows?`<section class="panel office-calendar-panel"><label class="parameter-field" for="office-calendar-select"><span>Kantor Pertanahan</span><select id="office-calendar-select" ${owner.loading?'disabled':''}><option value="">${owner.loading?'Memuat data..':'Pilih Kantor Pertanahan'}</option>${owner.rows.map((item,index)=>`<option value="${index}" ${owner.selected===item?'selected':''} ${item.kantorId.trim()?'':'disabled'}>${esc(item.namaKantor)}</option>`).join('')}</select></label><div class="office-calendar-heading"><button type="button" class="icon-button" data-action="office-month" data-index="-1" aria-label="Bulan sebelumnya" ${calendar.month<=now.getMonth()?'disabled':''}>${icon('arrow',18)}</button><h2>${officeMonthName(calendar.month).slice(0,3)} ${calendar.year}</h2><button type="button" class="icon-button" data-action="office-month" data-index="1" aria-label="Bulan berikutnya" ${calendar.month>=11?'disabled':''}>${icon('arrow',18)}</button></div>${officeCalendarGrid(calendar)}${blocked?notice(op&&needsAuth(op)&&!state.authenticated?'Masuk ke akun untuk membaca kalender layanan.':'Pembacaan kalender belum siap pada build ini.'):!usable?notice('Pilih kantor dengan referensi yang tersedia.'):`${calendar.loading?'<p role="status">Memuat kalender layanan…</p>':''}${calendar.error?`${notice(esc(calendar.error),'error')}<button type="button" class="button secondary" data-action="office-calendar-reload">Coba lagi kalender</button>`:''}${calendar.rows?officeCalendarEventsView(calendar):''}`}${calendar.rows?'<button type="button" class="text-button" data-action="office-calendar-reload">Perbarui kalender</button>':''}</section>`:''}`;}
async function selectCalendarOffice(index){if(route!=='officecalendar'||!Number.isInteger(index)||index<0)return;const owner=getOfficeState();if(!Array.isArray(owner.rows)||!Object.hasOwn(owner.rows,index))return;owner.selected=owner.rows[index];Object.assign(owner.calendar,{office:null,loadedYear:null,rows:null,error:'',request:null,loading:false});renderOffice();await loadOfficeCalendar();}
async function loadOfficeCalendar(){if(route!=='officecalendar')return;const owner=getOfficeState(),calendar=owner.calendar,selected=owner.selected,op=officeOperation('KantorNearby/GetCalendar');if(!op||!state.connection.configured||!selected||!owner.rows?.includes(selected)||typeof selected.kantorId!=='string'||!selected.kantorId.trim()||calendar.loading||needsAuth(op)&&!state.authenticated)return;const epoch=sessionEpoch,request={},year=calendar.year,retain=calendar.office===selected&&calendar.loadedYear===year;calendar.request=request;calendar.loading=true;calendar.error='';if(!retain){calendar.rows=null;calendar.loadedYear=null;}calendar.office=selected;const current=()=>route==='officecalendar'&&flowResults.get('office:nearby')===owner&&owner.calendar===calendar&&calendar.request===request&&owner.selected===selected&&calendar.year===year&&epoch===sessionEpoch;renderOffice();try{const reply=await api('/api/execute',{method:'POST',body:{operationId:op.id,values:{kantorId:selected.kantorId,tahun:String(year)}}});if(!current())return;const rows=officeCalendarRows(reply.result);if(!rows)throw new Error('Respons kalender belum dikenali. Coba muat kembali.');calendar.rows=rows;calendar.loadedYear=year;state.results.set(op.id,reply.result);record('Kalender Kantor Pertanahan','success',`HTTP ${reply.result.status} · Kalender diterima`);}catch(error){if(!current())return;if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(error.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(error.message);return;}calendar.error=error.message;record('Kalender Kantor Pertanahan','error',`${error.code||'ERROR'} · ${error.message}`);}finally{if(current()){calendar.loading=false;calendar.request=null;renderOffice();}}}
function changeOfficeMonth(delta){if(route!=='officecalendar'||![1,-1].includes(delta))return;const owner=getOfficeState(),calendar=owner.calendar,now=new Date(),month=calendar.month+delta;if(calendar.year!==now.getFullYear()||month<now.getMonth()||month>11)return;calendar.month=month;renderOffice();}
