async function requestOfficeLocation(){if(!['office','officecalendar'].includes(route)||!officeOperation('kantornearby/getkantornearby')||!state.connection.configured)return;const owner=getOfficeState();if(owner.locationBusy||owner.loading)return;if(!navigator.geolocation){owner.error='Browser ini belum menyediakan pembacaan lokasi perangkat.';renderOffice();return;}const request={},epoch=sessionEpoch,view=route;owner.request=request;owner.locationBusy=true;owner.error='';const current=()=>route===view&&flowResults.get('office:nearby')===owner&&owner.request===request&&epoch===sessionEpoch;renderOffice();try{const position=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:20000,maximumAge:0}));if(!current())return;const {latitude,longitude}=position.coords;if(!Number.isFinite(latitude)||!Number.isFinite(longitude)||Math.abs(latitude)>90||Math.abs(longitude)>180)throw new Error('Lokasi perangkat belum valid. Coba kembali.');owner.position={latitude,longitude};owner.locationBusy=false;owner.request=null;await loadNearbyOffices(owner);}catch(error){if(!current())return;owner.error=error.code===1?'Izin lokasi belum diberikan. Izinkan lokasi pada browser, lalu coba kembali.':error.code===3?'Pembacaan lokasi melewati batas waktu. Coba kembali di tempat dengan penerimaan lokasi lebih baik.':error.code===2?'Lokasi perangkat belum tersedia. Periksa layanan lokasi perangkat, lalu coba kembali.':error.message||'Lokasi perangkat belum dapat dibaca.';}finally{if(current()){owner.locationBusy=false;owner.request=null;renderOffice();}}}
