function verificationStatusView(response){const status=nativeVerificationStatus(response);if(!status)return notice('Respons status verifikasi belum dikenali. Coba perbarui status.','error');if(status.error===true)return notice(`Status verifikasi belum dapat dibaca.${status.message?' '+esc(status.message):' Coba perbarui status.'}`,'error');const statuses={'0':{title:'Verifikasi dalam proses',description:'Permohonan verifikasi akun Anda sedang diproses.',icon:'clock',kind:'warning'},'1':{title:'Verifikasi disetujui',description:'Permohonan verifikasi akun Anda telah disetujui.',icon:'check',kind:'success'},'2':{title:'Verifikasi ditolak',description:'Permohonan verifikasi akun Anda ditolak.',icon:'warning',kind:'warning'}},known=Object.hasOwn(statuses,status.message),view=known?statuses[status.message]:{title:'Status verifikasi belum dikenali',description:'Layanan belum memberikan status yang dapat ditampilkan. Coba perbarui status.',icon:'info',kind:'neutral'};return `<section class="panel verification-status" role="status" aria-label="Hasil status verifikasi"><span class="square-icon ${view.kind==='success'?'mint':''}">${icon(view.icon,26)}</span><div>${badge('Status dari layanan',view.kind)}<h2>${view.title}</h2><p>${view.description}</p>${status.message==='2'&&status.data?`<p class="verification-reason"><strong>Keterangan dari layanan</strong><br>${esc(status.data)}</p>`:''}${!known&&status.message?`<p class="verification-code">Kode layanan: ${esc(status.message)}</p>`:''}</div></section>`;}
