function certificateFacts(pairs,lineBreaks=false){return `<dl class="certificate-facts">${pairs.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${certificateText(value,lineBreaks)}</dd></div>`).join('')}</dl>`;}
function certificateRecords(title,records,renderItem,emptyMessage='Tidak ada rincian yang dikembalikan layanan.'){const rows=Array.isArray(records)?records:[],size=10;const group=(start,end)=>rows.slice(start,end).map((item,index)=>`<article class="certificate-record" data-record-index="${start+index}">${renderItem(item,start+index)}</article>`).join('');let content='';if(rows.length>size){for(let i=0;i<rows.length;i+=size)content+=`<details class="certificate-range" ${i===0?'open':''}><summary>${i+1}–${Math.min(i+size,rows.length)} dari ${rows.length}</summary><div>${group(i,i+size)}</div></details>`;}else content=group(0,rows.length);return `<section class="certificate-section"><div class="certificate-section-heading"><h3>${esc(title)}</h3>${rows.length?`<span>${rows.length} data</span>`:''}</div>${content||(emptyMessage?`<p class="certificate-empty">${esc(emptyMessage)}</p>`:'')}</section>`;}
function certificateLocation(item){const address=item.Alamat===null||item.Alamat===undefined||item.Alamat===''?[item.TipeWilayah,item.NamaWilayah].filter(value=>value!==null&&value!==undefined&&value!=='').join(' '):item.Alamat;return `<p class="certificate-location">${certificateText(address||null)}</p><p class="certificate-area">Luas ${certificateText(item.Luas)} m2</p>${certificateMapControls(item.PersilId)}`;}
async function loadCertificateMap(button){const slot=button.closest('.certificate-map-wrapper')?.querySelector('.certificate-map-slot'),persilid=button.dataset.persilId,epoch=sessionEpoch,sequence=detailSequence;if(!slot||button.dataset.loading==='true'||typeof persilid!=='string'||!persilid.trim()||!state.authenticated)return;const op=state.operations.find(o=>o.endpoint==='legacy/GetParcelBoundaryById?persilid={value}'&&ready(o));if(!op){slot.innerHTML=notice('Pembacaan batas bidang belum tersedia pada build ini.');return;}button.dataset.loading='true';button.disabled=true;button.textContent='Memuat batas…';slot.innerHTML='<p class="certificate-empty">Memuat batas bidang dari layanan…</p>';try{const response=await api('/api/execute',{method:'POST',body:{operationId:op.id,values:{persilid}}});if(epoch!==sessionEpoch||sequence!==detailSequence||!slot.isConnected||!$('#modal').open)return;slot.innerHTML=`${parcelMapView(flowData(response.result))}<details class="json-details"><summary>Data batas dari layanan</summary><pre>${json(response.result.data)}</pre></details>`;record('Batas bidang sertipikat','success',`HTTP ${response.result.status} · Respons diterima`);}catch(e){if(epoch!==sessionEpoch)return;if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(e.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(e.message);return;}if(sequence!==detailSequence||!slot.isConnected||!$('#modal').open)return;slot.innerHTML=notice(esc(e.message),'error');record('Batas bidang sertipikat','error',`${e.code||'ERROR'} · ${e.message}`);}finally{if(epoch===sessionEpoch&&sequence===detailSequence&&button.isConnected){button.dataset.loading='false';button.disabled=false;button.textContent='Perbarui batas bidang';}}}
async function loadCertificateMaps(){const modal=$('#modal'),epoch=sessionEpoch,sequence=detailSequence,buttons=[...modal.querySelectorAll('[data-action="certificate-map"]')];let next=0;const worker=async()=>{while(next<buttons.length&&epoch===sessionEpoch&&sequence===detailSequence&&modal.open){const button=buttons[next++];if(button.isConnected)await loadCertificateMap(button);}};await Promise.all([worker(),worker()]);}
function certificateOwner(item){return `<h4>${certificateText(item.Nama)}</h4><p class="certificate-location">${certificateText(item.TempatTanggalLahir)}</p>`;}
function certificateSurvey(item){const wilayah=[item.TipeWilayah,item.NamaWilayah].filter(value=>value!==null&&value!==undefined&&value!=='').join(' ');return `<h4>${certificateText(item.Nomor)}</h4><p class="certificate-location">${certificateText(wilayah||null)}</p>${certificateFacts([['Luas',`${item.Luas??'-'} m2`],['Berlaku Sejak',item.BerlakuSejak]])}`;}
function certificateNote(item,index){return `<h4>Catatan ${index+1}</h4><div class="certificate-note">${[item.Kolom1,item.Kolom2,item.Kolom3,item.Kolom4].map(value=>`<p>${certificateText(value,true)}</p>`).join('')}</div>`;}
function certificateDetailView(response,endpoint,selectedItem={}){const data=flowData(response);if(endpoint==='Brankas/DetailSertipikatNew'&&isElectronicCertificate(data))return electronicCertificateDetailView(response,selectedItem);if(endpoint!=='legacy/GetInfoSertifikat'||!isAnalogCertificate(data))return result(response);const url=typeof response.downloadUrl==='string'&&/^\/api\/downloads?\/[a-zA-Z0-9_-]+$/.test(response.downloadUrl)?response.downloadUrl:null;return `<div class="certificate-detail"><section class="certificate-summary"><p class="certificate-kind">${certificateText(data.JenisHak)}</p><h3 class="certificate-number">${certificateText(data.Nomor)}</h3>${certificateFacts([['NIB',data.Persil?.[0]?.Nomor],['Kode Blanko',data.KodeBlanko],['Tanggal Penerbitan',data.ValidSejak],['Berlaku Sampai',data.ValidSampai]])}</section>${certificateRecords('Lokasi Bidang Tanah',data.Persil,certificateLocation)}${certificateRecords('Pemilik',data.PemilikPertama,certificateOwner)}${certificateRecords('Surat Ukur',data.SuratUkur,certificateSurvey)}${certificateRecords('Catatan Pendaftaran',data.CatatanPendaftaran,certificateNote)}${url?`<a class="button secondary" href="${esc(url)}" download>${icon('download',16)} Unduh lampiran</a>`:''}<details class="json-details certificate-technical"><summary>Pratinjau respons JSON</summary><p>Pratinjau JSON dibatasi untuk respons panjang. Semua rincian pada bagian di atas tetap tersedia.</p><pre>${json(data)}</pre></details></div>`;}
async function loadCertificateDetail(item){const selectedItem=certificateListItem(item),target=certificateDetailTarget(item),epoch=sessionEpoch,sequence=detailSequence;const op=target&&state.operations.find(o=>o.endpoint===target.endpoint&&ready(o)&&!write(o));if(!op||!state.authenticated)return;const header=`<div class="modal-heading"><div><div class="eyebrow">SERTIPIKATKU</div><h2 id="modal-title">Detail sertipikat</h2></div><button class="icon-button" data-action="modal-close" aria-label="Tutup dialog">${icon('close')}</button></div>`;$('#modal').innerHTML=`${header}<div class="modal-body">${empty('Memuat detail sertipikat…','Mengambil informasi dari layanan.','clock')}</div>`;$('#modal').showModal();try{const response=await api('/api/execute',{method:'POST',body:{operationId:op.id,values:target.values}});if(epoch!==sessionEpoch||sequence!==detailSequence)return;record('Detail sertipikat','success',`HTTP ${response.result.status} · Respons diterima`);if(!$('#modal').open)return;$('#modal').innerHTML=`${header}<div class="modal-body">${certificateDetailView(response.result,target.endpoint,selectedItem)}<div class="modal-actions"><button class="button secondary" data-action="modal-close">Tutup</button></div></div>`;await loadCertificateMaps();}catch(e){if(epoch!==sessionEpoch)return;if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(e.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(e.message);return;}if(sequence!==detailSequence)return;record('Detail sertipikat','error',`${e.code||'ERROR'} · ${e.message}`);if($('#modal').open)$('#modal').innerHTML=`${header}<div class="modal-body">${notice(esc(e.message),'error')}<button class="button secondary" data-action="modal-close">Tutup</button></div>`;}}
function detailSection(title,value){if(value===undefined||value===null)return '';const items=Array.isArray(value)?value:[value];return `<section class="service-detail-section"><h3>${title}</h3>${items.length?`<ol>${items.map(item=>`<li>${typeof item==='object'?facts(item,20):esc(item)}</li>`).join('')}</ol>`:'<p>Tidak ada rincian yang dikembalikan layanan.</p>'}</section>`;}
function nativeInformationBody(response){if(response?.status!==200)return null;let body=response.data;if(typeof body==='string'){try{body=JSON.parse(body);}catch{return null;}}return body&&typeof body==='object'&&!Array.isArray(body)&&body.error!==true?body:null;}
function isInformationItem(item){return !!item&&typeof item==='object'&&!Array.isArray(item)&&['layananId','nama','deskripsi','grup'].every(key=>item[key]==null||typeof item[key]==='string')&&(item.tipeSimulasi==null||Number.isInteger(item.tipeSimulasi));}
function informationRows(response){const rows=nativeInformationBody(response)?.data;return Array.isArray(rows)&&rows.every(isInformationItem)?rows:null;}
function informationDetail(response){const detail=nativeInformationBody(response)?.data;return detail&&typeof detail==='object'&&!Array.isArray(detail)&&['layananId','nama','tarif'].every(key=>detail[key]==null||typeof detail[key]==='string')&&['persayaratan','penyelesaian','keterangan'].every(key=>detail[key]==null||Array.isArray(detail[key])&&detail[key].every(item=>typeof item==='string'))&&(detail.tipeSimulasi==null||Number.isInteger(detail.tipeSimulasi))?detail:null;}
function getInformationState(){let owner=flowResults.get('information:default');if(!owner?.information){owner={information:true,attempted:false,scheduled:false,loading:false,rows:null,error:'',query:'',listRequest:null,detail:null};flowResults.set('information:default',owner);}return owner;}
function informationGroups(rows,query=''){const groups=new Map(),needle=query.toLowerCase();rows.forEach((item,index)=>{if(needle&&!['nama','deskripsi','grup'].some(key=>typeof item[key]==='string'&&item[key].toLowerCase().includes(needle)))return;const label=item.grup??'Lainnya';if(!groups.has(label))groups.set(label,[]);groups.get(label).push({item,index});});return [...groups].map(([label,items])=>({label,items}));}
function informationListView(owner){const groups=informationGroups(owner.rows||[],owner.query);if(!groups.length)return `<section class="panel flow-empty">${empty(owner.rows?.length?'Layanan tidak ditemukan.':'Tidak ada data informasi layanan.','','folder')}</section>`;return `<div class="information-groups">${groups.map(group=>`<section class="information-group"><h2>${esc(group.label)}</h2><div class="information-list">${group.items.map(({item,index})=>`<button class="information-item" data-action="flow-detail" data-index="${index}" ${typeof item.layananId==='string'&&item.layananId.trim()?'':'disabled'}><span><strong>${esc(item.nama??'-')}</strong><span>${esc(item.deskripsi??'-')}</span></span>${icon('chevron',20)}</button>`).join('')}</div></section>`).join('')}</div>`;}
function informationSection(title,items){return items?.length?`<section class="service-detail-section"><h3>${title}</h3><ol>${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ol></section>`:'';}
function informationDetailView(owner){const frame=owner.detail,details=frame?.response&&informationDetail(frame.response);const back=`<div class="information-back"><button class="button secondary small" data-action="information-back">${icon('arrow',16)} Kembali ke daftar layanan</button></div>`;if(frame?.loading)return `${head('INFO LAYANAN',esc(frame.item.nama??'Detail layanan'),'')}${back}<section class="panel flow-empty">${empty('Memuat detail layanan…','Mengambil informasi dari layanan.','clock')}</section>`;if(!details)return `${head('INFO LAYANAN',esc(frame?.item.nama??'Detail layanan'),'')}${back}${notice(`Gagal memuat detail layanan.${frame?.error?' '+esc(frame.error):''}`,'error')}<button class="button secondary" data-action="information-detail-retry">Coba lagi</button>`;return `${head('INFO LAYANAN',esc(details.nama??''),'')}${back}<section class="panel information-detail">${frame.item.deskripsi?`<p class="information-description">${esc(frame.item.deskripsi)}</p>`:''}${informationSection('Persyaratan',details.persayaratan)}${informationSection('Waktu Penyelesaian',details.penyelesaian)}${informationSection('Keterangan Tambahan',details.keterangan)}${details.tarif!=null?`<section class="service-detail-section"><h3>Tarif</h3><p>${esc(details.tarif)}</p></section>`:''}${informationSimulationView(owner,frame,details)}</section>`;}
function informationPage(){const owner=getInformationState(),op=state.operations.find(op=>op.endpoint==='InfoLayanan/GetInfoLayanan'&&ready(op)&&!write(op)),available=!!op&&state.connection.configured&&!state.loading;if(available&&!owner.attempted&&!owner.scheduled){owner.scheduled=true;queueMicrotask(()=>{owner.scheduled=false;if(route==='information'&&flowResults.get('information:default')===owner&&!owner.attempted)loadInformationList();});}if(owner.detail)return informationDetailView(owner);return `${head('SENTUH TANAHKU','Info Layanan','Temukan informasi dan persyaratan pengurusan pertanahan.')}<section class="panel information-controls"><label class="native-list-search">Cari layanan<input id="flow-search" type="search" placeholder="Cari layanan" value="${esc(owner.query)}" autocomplete="off"></label><button class="button secondary" data-action="information-load" ${!available||owner.loading?'disabled':''}>${icon('refresh',16)} ${owner.loading?'Memuat…':owner.error?'Coba lagi':'Perbarui'}</button></section>${!state.connection.configured?notice(esc(state.connection.reason||'Koneksi belum dikonfigurasi.')):!op&&!state.loading?notice('Informasi layanan belum tersedia pada build ini.') :''}${owner.loading||!owner.attempted?`<section class="panel flow-empty">${empty('Memuat informasi layanan…','Tunggu respons layanan.','clock')}</section>`:owner.error?notice(`Gagal memuat data. Silakan coba lagi. ${esc(owner.error)}`,'error'):informationListView(owner)}`;}
async function loadInformationList(){if(route!=='information'||!state.connection.configured||state.loading)return;const owner=getInformationState(),op=state.operations.find(op=>op.endpoint==='InfoLayanan/GetInfoLayanan'&&ready(op)&&!write(op));if(!op||owner.loading)return;const epoch=sessionEpoch,request={};owner.attempted=true;owner.loading=true;owner.error='';owner.rows=null;owner.detail=null;owner.listRequest=request;const current=()=>route==='information'&&flowResults.get('information:default')===owner&&owner.listRequest===request&&epoch===sessionEpoch;render();try{const response=await api('/api/execute',{method:'POST',body:{operationId:op.id,values:{}}});if(!current())return;const rows=informationRows(response.result);if(!rows)throw new Error('Respons informasi layanan belum dikenali.');owner.rows=rows;state.results.set(op.id,response.result);record('Info Layanan','success',`HTTP ${response.result.status} · Respons diterima`);}catch(error){if(!current())return;owner.error=error.message;state.results.delete(op.id);record('Info Layanan','error',`${error.code||'ERROR'} · ${error.message}`);if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(error.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(error.message);}}finally{if(current()){owner.loading=false;owner.listRequest=null;render();}}}
function openInformationDetail(index){if(route!=='information'||!Number.isInteger(index)||index<0)return;const owner=getInformationState(),item=owner.rows?.[index];if(!isInformationItem(item)||typeof item.layananId!=='string'||!item.layananId.trim())return;return loadServiceDetail(item);}
async function loadServiceDetail(item){if(route!=='information'||!state.connection.configured)return;const owner=getInformationState();if(!owner.rows?.includes(item)||!isInformationItem(item)||typeof item.layananId!=='string'||!item.layananId.trim())return;const op=state.operations.find(op=>op.endpoint==='InfoLayanan/GetInfoLayananDetail?id={value}'&&ready(op)&&!write(op));if(!op)return;if(owner.detail?.item===item&&owner.detail.loading)return;const epoch=sessionEpoch,request={},frame={item,response:null,loading:true,error:'',request};owner.detail=frame;const current=()=>route==='information'&&flowResults.get('information:default')===owner&&owner.detail===frame&&frame.request===request&&epoch===sessionEpoch;render();window.scrollTo(0,0);try{const response=await api('/api/execute',{method:'POST',body:{operationId:op.id,values:{id:item.layananId}}});if(!current())return;if(!informationDetail(response.result))throw new Error('Respons detail layanan belum dikenali.');frame.response=response.result;record('Detail Info Layanan','success',`HTTP ${response.result.status} · Respons diterima`);}catch(error){if(!current())return;frame.error=error.message;record('Detail Info Layanan','error',`${error.code||'ERROR'} · ${error.message}`);if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(error.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(error.message);}}finally{if(current()){frame.loading=false;frame.request=null;render();}}}
function backInformation(){if(route!=='information')return;const owner=getInformationState();owner.detail=null;render();window.scrollTo(0,0);}
function filterInformation(input){if(route!=='information'||!input.isConnected)return;const owner=getInformationState();if(owner.detail)return;const start=input.selectionStart,end=input.selectionEnd;owner.query=input.value;render();const replacement=$('#flow-search');if(replacement){replacement.focus({preventScroll:true});if(start!==null&&end!==null)replacement.setSelectionRange(start,end);}}
function nativeAccountSummary(response){const body=nativeResponseObject(response),profile=body?.data;return response?.status===200&&body?.error===false&&profile&&typeof profile==='object'&&!Array.isArray(profile)?profile:null;}
function visibleNativeMenus(){const op=state.operations.find(o=>o.endpoint==='account/account_summary');const profile=state.authenticated&&op?nativeAccountSummary(state.results.get(op.id)):null;const eligible=profile&&profile.roleUser==='PERORANGAN'&&Number.isInteger(profile.statusVerifikasi)&&profile.statusVerifikasi!==-1&&![true,'true','1'].includes(profile.isIkd);return eligible?primaryMenus:primaryMenus.filter(([key])=>!['collections','activity'].includes(key));}
async function refreshNativeProfile(accept=()=>true){const op=state.operations.find(o=>o.endpoint==='account/account_summary'&&ready(o)&&!write(o));if(!state.authenticated||logoutPending||!op||!accept())return;const epoch=sessionEpoch,key='accountsummary:default',request={loading:true,profileAuto:true},current=()=>epoch===sessionEpoch&&flowResults.get(key)===request&&accept();flowResults.set(key,request);try{const data=await api('/api/execute',{method:'POST',body:{operationId:op.id,values:{}}});if(!current())return;if(!nativeAccountSummary(data.result))throw new Error('Respons profil belum dikenali. Coba muat profil kembali.');state.results.set(op.id,data.result);Object.assign(request,{response:data.result,loading:false});state.profileError='';record('Profil akun','success',`HTTP ${data.result.status} · Respons diterima`);}catch(e){if(!current())return;Object.assign(request,{error:e.message,loading:false});state.results.delete(op.id);state.profileError=e.message;record('Profil akun','error',`${e.code||'ERROR'} · ${e.message}`);if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(e.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(e.message);}}}
function account(){return `${head('SENTUH TANAHKU','Profil','Kelola akun dan akses informasi aplikasi.')}<div class="profile-layout"><div>${loginCard()}${state.authenticated?`<section class="panel profile-account-actions"><h2>Informasi akun</h2><a href="#/accountsummary">Data akun ${icon('chevron',16)}</a><a href="#/verification">Status verifikasi ${icon('chevron',16)}</a><a href="#/collections">Koleksi ${icon('chevron',16)}</a><a href="#/activity">Aktivitas ${icon('chevron',16)}</a></section>`:''}</div><div><section class="panel profile-menu"><h2>Pengaturan & informasi</h2>${profileMenus.map(m=>`<a href="#/${m.route}"><span>${m.asset?`<img src="assets/icons/${m.asset}" alt="">`:icon(m.icon,21)}</span><strong>${m.label}</strong>${icon('chevron',16)}</a>`).join('')}${state.authenticated?`<button data-action="logout"><span>${icon('user',21)}</span><strong>Keluar</strong>${icon('chevron',16)}</button>`:''}</section>${state.profileError?notice(`Informasi profil belum dapat dimuat: ${esc(state.profileError)} <a class="text-link" href="#/accountsummary">Coba muat profil</a>`,'error'):''}<details class="profile-connection panel"><summary>Koneksi browser</summary><dl class="detail-list"><div><dt>Tujuan layanan</dt><dd>${esc(state.connection.origin||'Belum tersedia')}</dd></div><div><dt>Versi sumber</dt><dd>${esc(state.version)}</dd></div></dl>${state.connection.reason?notice(esc(state.connection.reason)):''}<a class="text-link" href="#/testing">Buka pengujian lanjutan ${icon('arrow',14)}</a></details></div></div>`;}
function externalPage(){const page=externalPages[route];return `${head('INFORMASI',page.title,'Buka halaman yang digunakan oleh aplikasi Sentuh Tanahku.')}<section class="panel external-service"><span class="square-icon">${icon('wifi',25)}</span><h2>${page.title}</h2><p>Halaman ini dibuka di situs tujuan melalui tab browser baru.</p><code>${esc(page.url)}</code><a class="button" href="${esc(page.url)}" target="_blank" rel="noopener noreferrer">Buka ${page.title} ${icon('arrow',17)}</a></section>`;}
function profileSection(){if(route==='security')return `${head('PROFIL','Akun dan Keamanan','Informasi akun dan status verifikasi Anda.')}<div class="service-directory"><a class="service-directory-card" href="#/accountsummary"><span class="square-icon">${icon('user')}</span><div><h2>Data akun</h2><p>Lihat informasi akun yang dikembalikan layanan.</p></div>${icon('chevron')}</a><a class="service-directory-card" href="#/verification"><span class="square-icon mint">${icon('shield')}</span><div><h2>Status verifikasi</h2><p>Periksa status verifikasi akun Anda.</p></div>${icon('chevron')}</a></div><section class="panel profile-gap"><h2>Perubahan akun</h2><p>Perubahan kata sandi, identitas, dan alur verifikasi native belum tersedia pada antarmuka browser ini.</p></section>`;if(route==='settings')return `${head('PROFIL','Pengaturan','Pengaturan sesi browser dan informasi versi.')}<section class="panel"><dl class="detail-list"><div><dt>Versi sumber APK</dt><dd>${esc(state.version)}</dd></div><div><dt>Penyimpanan koordinat</dt><dd>Memori tab browser</dd></div><div><dt>Sesi akun</dt><dd>${state.authenticated?'Terhubung':'Belum masuk'}</dd></div></dl><p class="settings-note">Pengaturan khusus Android belum dipindahkan ke browser. Data sesi lokal dibersihkan saat keluar akun atau memuat ulang halaman.</p><a class="button secondary" href="#/testing">Diagnostik koneksi ${icon('arrow',16)}</a></section>`;if(route==='benefits')return `${head('PROFIL','Keuntungan Pakai Sentuh Tanahku','Akses informasi pertanahan melalui fitur aplikasi.')}<section class="panel benefits-list"><h2>Informasi dalam satu tempat</h2><p>Lihat sertipikat dan akta pada akun Anda, pantau berkas, serta temukan informasi persyaratan layanan pertanahan.</p><a href="#/services" class="button">Lihat layanan ${icon('arrow',16)}</a></section>`;if(['contact','faq'].includes(route))return `${head('PROFIL',esc(routes[route]),'Akses bantuan untuk penggunaan Sentuh Tanahku.')}<section class="panel external-service"><span class="square-icon">${icon('info',25)}</span><h2>Pusat bantuan Sentuh Tanahku</h2><p>Halaman bantuan yang tercantum pada menu Informasi APK tersedia melalui situs ATR/BPN.</p><a class="button" href="https://bantuan.atrbpn.go.id/sentuhtanahku/" target="_blank" rel="noopener noreferrer">Buka bantuan ${icon('arrow',17)}</a></section>`;return `${head('PROFIL',esc(routes[route]),'Informasi ketersediaan menu aplikasi.')}<section class="panel unavailable-feature"><span class="square-icon">${icon(route==='privacy'?'shield':'info',25)}</span><h2>${route==='privacy'?'Halaman kebijakan belum dipetakan':'Penilaian aplikasi belum tersedia di browser'}</h2><p>${route==='privacy'?'Tujuan halaman Kebijakan Privasi pada alur Profil belum terverifikasi. Gunakan menu asli pada aplikasi Android untuk membaca kebijakan layanan.':'Gunakan menu Beri Kami Nilai pada aplikasi Android untuk membuka tujuan penilaian yang sesuai.'}</p><a class="button secondary" href="#/account">Kembali ke profil</a></section>`;}

