// Mitra list models and parent selection follow the bounded APK evidence in MITRA-FLOW.md.
function resetPartnerNavigation(){if(partnerFrame&&flowResults.get(partnerFrame.key)?.loading)flowResults.delete(partnerFrame.key);partnerFrame=null;}
function partnerFlowContext(def){if(!partnerFrame){const tab=def.tabs.find(t=>t.id===flowTab&&!t.parent)||def.tabs.find(t=>!t.parent);partnerFrame={tabId:tab.id,key:`partners:${tab.id}`,values:{},parent:null,title:null,kind:'0',query:'',page:0};}const original=def.tabs.find(t=>t.id===partnerFrame.tabId);if(!original)return null;const tab={...original,values:partnerFrame.values,form:false};return {def,tab,key:partnerFrame.key,partnerFrame,op:state.operations.find(o=>o.endpoint===tab.endpoint&&ready(o))||state.operations.find(o=>o.endpoint===tab.endpoint)};}
function partnerItem(mode,item){if(!item||typeof item!=='object'||Array.isArray(item))return null;const fields={kantorppat:['kantorId','nama'],wilayah:['wilayahId','nama'],penilai:['nama'],ppat:['nama','alamatKantor','tmtPensiun','totalAkta','isPPAT','nomorSK'],surveyor:['nama','jenisSurveyor','nomorLisensi']}[mode];if(!fields)return null;const ignored={kantorppat:['kode'],ppat:['tempatKedudukan','status']}[mode]||[];if([...fields,...ignored].some(key=>item[key]!=null&&typeof item[key]!=='string'))return null;return Object.fromEntries(fields.map(key=>[key,item[key]??null]));}
