function partnerListView(c,response){const rows=partnerRows(c.tab.id,response);if(rows===null)return `<section class="panel">${notice('Bentuk daftar mitra belum dikenali. Tidak ada referensi yang dipilih dari respons ini.')}<details class="json-details"><summary>Data dari layanan</summary><pre>${json(response.data)}</pre></details></section>`;const items=rows.map((item,index)=>({item,index})).filter(({item})=>partnerItemMatches(c.tab.id,item,flowQuery,c.partnerFrame.kind)),placeholder={kantorppat:'Cari kota',wilayah:'Cari provinsi',penilai:'Cari penilai pertanahan',ppat:'Cari PPAT',surveyor:'Cari surveyor'}[c.tab.id];flowPageIndex=Math.min(flowPageIndex,Math.max(0,Math.ceil(items.length/20)-1));const start=flowPageIndex*20,search=`<label class="native-list-search">${placeholder}<input id="flow-search" type="search" placeholder="${placeholder}" value="${esc(flowQuery)}" autocomplete="off"></label>`;return search+(items.length?`<div class="server-data-heading"><span>${start+1}–${Math.min(start+20,items.length)} dari ${items.length} item ditampilkan</span>${badge('Respons server','success')}</div><div class="data-card-grid">${items.slice(start,start+20).map(({item,index})=>partnerCard(c.tab.id,item,index)).join('')}</div>${listPagination(items.length,start)}`:empty('Data Tidak Ditemukan','Tidak ada mitra yang cocok dengan pilihan ini.','folder'));}
function partnerPage(){const c=currentFlow();if(!c)return unavailablePage();const {def,tab,op,key}=c,r=flowResults.get(key),frame=c.partnerFrame,rootId=frame.parent?.tabId||tab.id,blocked=!op||!ready(op)||write(op),requires=op&&needsAuth(op),labels=tab.id==='ppat'?['PPAT','PPATS']:tab.id==='surveyor'?['Surveyor','Asisten Surveyor']:null;return `${head('MITRA KERJA',frame.title||def.title,def.subtitle)}${frame.parent?`<div class="partner-back"><button class="button secondary small" data-action="partner-back">${icon('arrow',15)} Kembali ke ${tab.id==='ppat'?'daftar kantor':'daftar wilayah'}</button></div>`:''}<div class="service-tabs" role="tablist" aria-label="Jenis Mitra Kerja">${def.tabs.filter(t=>!t.parent).map(t=>`<button role="tab" aria-selected="${rootId===t.id}" class="${rootId===t.id?'active':''}" data-action="partner-tab" data-id="${t.id}">${esc(t.label)}</button>`).join('')}</div>${labels?`<div class="service-tabs" role="tablist" aria-label="Kategori ${esc(tab.label)}">${labels.map((label,i)=>`<button role="tab" aria-selected="${frame.kind===String(i)}" class="${frame.kind===String(i)?'active':''}" data-action="partner-kind" data-id="${i}">${label}</button>`).join('')}${tab.id==='ppat'?`<button class="text-button" data-action="partner-info" aria-label="Informasi jumlah akta">${icon('info',17)}</button>`:''}</div>`:''}${requires&&!state.authenticated?`<section class="panel service-login-gate"><h2>Masuk untuk membuka ${esc(tab.label)}</h2><a class="button" href="#/account">Masuk ke akun</a></section>`:`<section class="panel flow-controls"><div class="flow-load-row"><div><h2>${esc(frame.title||({kantorppat:'Kantor PPAT',wilayah:'Wilayah Surveyor',penilai:'Penilai Tanah'}[tab.id]||tab.label))}</h2><p>${r?.response?'Data terakhir diterima dari layanan.':'Data belum dimuat pada sesi ini.'}</p></div><button class="button" data-action="flow-load" ${blocked||!state.connection.configured||r?.loading?'disabled':''}>${icon('refresh',16)} ${r?.loading?'Memuat…':r?.error?'Coba lagi':r?.response?'Perbarui':'Tampilkan data'}</button></div>${blocked?notice(esc(op?.reason||'Pembacaan mitra belum tersedia.')):''}${!state.connection.configured?notice(esc(state.connection.reason||'Koneksi belum dikonfigurasi.')):''}</section>${r?.error?notice(esc(r.error),'error'):''}${r?.response?partnerListView(c,r.response):!blocked?empty(r?.loading?'Memuat data dari layanan…':'Siap menampilkan data',r?.loading?'Tunggu respons layanan.':'Tekan Tampilkan data untuk mengambil informasi dari server.','folder'):''}`}`;}
async function openPartnerItem(index){const c=currentFlow();if(route!=='partners'||!c?.partnerFrame||!Number.isInteger(index)||index<0)return;const rows=partnerRows(c.tab.id,flowResults.get(c.key)?.response);if(!rows||!Object.hasOwn(rows,index))return;const target=partnerChildTarget(c.tab.id,rows[index]);if(!target)return;const op=state.operations.find(o=>o.endpoint===target.endpoint&&ready(o)&&!write(o));if(!op||!state.connection.configured||needsAuth(op)&&!state.authenticated){toast('Pembacaan daftar mitra belum tersedia.');return;}const parent=c.partnerFrame;parent.query=flowQuery;parent.page=flowPageIndex;partnerFrame={tabId:target.tabId,key:`partners:${JSON.stringify([target.endpoint,target.values])}`,values:Object.freeze({...target.values}),title:target.title,parent,kind:'0',query:'',page:0};flowTab=target.tabId;flowQuery='';flowPageIndex=0;detailSequence++;$('#modal').close();await runFlow();}
