function filterPartnerFlow(input){const c=currentFlow();if(route!=='partners'||!input.isConnected||!c?.partnerFrame||c.op&&needsAuth(c.op)&&!state.authenticated)return;const start=input.selectionStart,end=input.selectionEnd;flowQuery=input.value;c.partnerFrame.query=flowQuery;flowPageIndex=0;render();const replacement=$('#flow-search');if(replacement){replacement.focus({preventScroll:true});if(start!==null&&end!==null)replacement.setSelectionRange(start,end);}}
