// Cari Berkas: native office selection, local challenge and ordered reads.
function generateSearchFileCaptcha(){let value='';while(value.length<6){const bytes=crypto.getRandomValues(new Uint8Array(12));for(const byte of bytes){if(byte<250)value+=String(byte%10);if(value.length===6)break;}}return value;}
function searchFileYears(){const year=new Date().getFullYear();return [String(year-1),String(year)];}
function getSearchFileState(){if(!searchFileState)searchFileState={offices:null,officeStatus:'idle',officeError:'',officeQuery:'',officePage:0,selectedOffice:null,nomor:'',tahun:searchFileYears()[1],captcha:generateSearchFileCaptcha(),captchaInput:'',errors:{},busy:false,message:'',response:null,sop:null,print:'-',request:null,officeRequest:null};return searchFileState;}
function resetSearchFileNavigation(){searchFileState=null;flowResults.delete('searchfile:default');}
function searchFileOperation(endpoint){return state.operations.find(op=>op.endpoint===endpoint&&ready(op)&&!write(op))||null;}
function searchFileTyped(row,spec){if(!row||typeof row!=='object'||Array.isArray(row))return null;const value={};for(const [key,type] of Object.entries(spec)){const field=row[key]??null;if(field!==null&&!(type==='s'?typeof field==='string':type==='i'?Number.isInteger(field):type==='b'?typeof field==='boolean':typeof field==='number'&&Number.isFinite(field)))return null;value[key]=field;}return value;}
function searchFileOfficeRows(response){if(response?.status!==200||!Array.isArray(response.data))return null;const rows=response.data.map(row=>searchFileTyped(row,{Alamat:'s',Email:'s',Fax:'s',KantorId:'s',Nama:'s',Telp:'s',Kota:'s',TipeKantorId:'i'}));return rows.every(Boolean)?rows:null;}
function searchFileOfficeMatches(row,query){return (row.Nama??'').toLowerCase().includes(query.toLowerCase().trim());}
function searchFileOfficeEntries(owner){const profile=nativeAccountSummary(flowResults.get('accountsummary:default')?.response),preferred=typeof profile?.kantorId==='string'?profile.kantorId:null,entries=(owner.offices||[]).map((item,index)=>({item,index,preferred:preferred!==null&&item.KantorId===preferred})),first=entries.findIndex(row=>row.preferred);if(first>0)entries.unshift(entries.splice(first,1)[0]);return entries;}
function searchFileSopModel(row){return searchFileTyped(row,{lewatTenggat:'b',tanggalTenggat:'s',berkasDibuat:'s',berkasSelesai:'s',tipeProduk:'s'});}
function searchFileBerkasModel(row){const value=searchFileTyped(row,{berkasId:'s',statusBerkas:'i',nomor:'i',tahun:'i',tanggalDibuat:'s',tanggalSelesai:'s',namaProsedur:'s',namaPemilik:'s',namaPegawai:'s',namaProfile:'s',biaya:'n',statusCetak:'s',allowGeotag:'i',kodeSPOPP:'s'});if(!value)return null;for(const [key,raw,spec] of [['perjalananBerkas',row.perjalananBerkas??row.PerjalananBerkas,{taskNodeGroupId:'s',tanggalFlow:'s',namaGrup:'s',isCurrent:'b'}],['parapihak',row.parapihak,{pemilikId:'s',tipePemilik:'s',nama:'s',tempatTanggalLahir:'s'}],['fileSps',row.fileSps,{spsId:'s',tipe:'s',alias:'s',tanggal:'s'}]]){if(raw==null)value[key]=null;else{if(!Array.isArray(raw))return null;value[key]=raw.map(item=>searchFileTyped(item,spec));if(!value[key].every(Boolean))return null;}}if(row.kantor==null)value.kantor=null;else{value.kantor=searchFileTyped(row.kantor,{nama:'s',alamat:'s',telp:'s',fax:'s',email:'s',tipeKantorId:'s'});if(!value.kantor)return null;}if(row.fileSop==null)value.fileSop=null;else{value.fileSop=searchFileSopModel(row.fileSop);if(!value.fileSop)return null;}return value;}
function searchFilePrimary(response){const body=response?.data;if(response?.status!==200||!body||typeof body!=='object'||Array.isArray(body))return null;return searchFileBerkasModel(body.data);}
function searchFileSop(response){const body=response?.data;if(response?.status!==200||!body||typeof body!=='object'||Array.isArray(body)||body.error!=null&&typeof body.error!=='boolean'||body.error===true)throw new Error('Informasi SOP berkas belum dapat dibaca.');const model=searchFileSopModel(body.data??{});if(!model)throw new Error('Bentuk informasi SOP berkas belum dikenali.');return model;}
function searchFilePrint(response){const body=response?.data;if(!body||typeof body!=='object'||Array.isArray(body)||body.error!=null&&typeof body.error!=='boolean'||body.message!=null&&typeof body.message!=='string')return '-';return body.message??'-';}
function renderSearchFile(){const active=document.activeElement,name=active?.closest?.('#searchfile-form')&&['nomor','tahun','captcha'].includes(active.name)?active.name:null,start=active?.selectionStart,end=active?.selectionEnd;render();renderSearchFilePicker();const input=name&&$('#searchfile-form')?.elements.namedItem(name);if(input){input.focus({preventScroll:true});if(start!=null&&end!=null&&typeof input.setSelectionRange==='function')input.setSelectionRange(start,end);}}
function refreshSearchFileCaptcha(){if(route!=='searchfile'||!state.authenticated||!searchFileState||searchFileState.busy)return;searchFileState.captcha=generateSearchFileCaptcha();renderSearchFile();}
async function loadSearchFileOffices(owner=searchFileState){const op=searchFileOperation('legacy/Kantah?nama={value}&tipeKantor={value}');if(route!=='searchfile'||!owner||owner!==searchFileState||!state.authenticated||!state.connection.configured||!op||owner.officeStatus==='loading')return;const epoch=sessionEpoch,request={};owner.officeRequest=request;owner.officeStatus='loading';owner.officeError='';const current=()=>route==='searchfile'&&owner===searchFileState&&owner.officeRequest===request&&epoch===sessionEpoch&&state.authenticated;renderSearchFile();try{const reply=await api('/api/execute',{method:'POST',body:{operationId:op.id,values:{nama:'',tipeKantor:'3,2,1'}}});if(!current())return;const rows=searchFileOfficeRows(reply.result);if(rows===null)throw new Error('Bentuk daftar kantor belum dikenali.');owner.offices=rows;owner.officeStatus='ready';if(owner.selectedOffice&&!rows.includes(owner.selectedOffice))owner.selectedOffice=null;record('Daftar kantor pertanahan','success',`HTTP ${reply.result.status} · Respons diterima`);}catch(error){if(!current())return;if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(error.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(error.message);return;}owner.officeStatus='error';owner.officeError=error.message;}finally{if(current())renderSearchFile();}}
function searchFileResultView(owner){if(!owner.response)return '';const sop=owner.sop?.tipeProduk==='Rutin'?`<span class="berkas-sop ${owner.sop.lewatTenggat===true?'berkas-sop-late':'berkas-sop-ontime'}">${owner.sop.lewatTenggat===true?'Lewat SOP':'Sesuai SOP'}</span>`:'',print=owner.print!==''&&owner.print!=='-'?`<p class="berkas-print-status"><strong>Status Cetak</strong><span>${esc(owner.print)}</span></p>`:'';return `<section class="panel searchfile-result">${berkasDetailView(owner.response,{prefetchedSop:sop,prefetchedPrint:print,bookmark:berkasBookmarkForDetail(owner.response,{kind:'search',sourceOwner:owner})})}</section>`;}
async function submitSearchFile(form){if(route!=='searchfile'||!state.authenticated||!form?.isConnected||!state.connection.configured)return;const owner=getSearchFileState();if(owner.busy)return;for(const [name,key] of [['nomor','nomor'],['tahun','tahun'],['captcha','captchaInput']]){const input=form.elements.namedItem(name);if(input)owner[key]=input.value;}const errors={};if(!owner.selectedOffice||!(owner.offices||[]).includes(owner.selectedOffice)||typeof owner.selectedOffice.KantorId!=='string'||!owner.selectedOffice.KantorId.trim())errors.kantorId='Pilih Kantor Pertanahan';if(typeof owner.nomor!=='string'||owner.nomor.length===0)errors.nomor='Nomor berkas tidak boleh kosong';if(typeof owner.tahun!=='string'||owner.tahun.length===0)errors.tahun='Tahun tidak boleh kosong';if(owner.captchaInput!==owner.captcha)errors.captcha='Captcha salah';owner.errors=errors;if(Object.keys(errors).length){renderSearchFile();return;}const primaryOp=searchFileOperation('/berkas/CariBerkas'),sopOp=searchFileOperation('berkas/berkassop'),printOp=searchFileOperation('berkas/getStatusCetak');if(!primaryOp||!sopOp||!printOp){owner.message='Pembacaan berkas belum tersedia pada build ini.';renderSearchFile();return;}const epoch=sessionEpoch,request={};owner.request=request;owner.busy=true;owner.message='';owner.response=null;owner.sop=null;owner.print='-';const current=()=>route==='searchfile'&&owner===searchFileState&&owner.request===request&&epoch===sessionEpoch&&state.authenticated;renderSearchFile();try{const primary=await api('/api/execute',{method:'POST',body:{operationId:primaryOp.id,values:{nomor:owner.nomor,tahun:owner.tahun,kantorId:owner.selectedOffice.KantorId,berkasId:null}}});if(!current())return;const data=searchFilePrimary(primary.result);if(!data||typeof data.berkasId!=='string'||!data.berkasId.trim())throw new Error('Berkas tidak ditemukan.');const sopReply=await api('/api/execute',{method:'POST',body:{operationId:sopOp.id,values:{berkasid:data.berkasId}}});if(!current())return;const sop=searchFileSop(sopReply.result);let print='-';try{const printReply=await api('/api/execute',{method:'POST',body:{operationId:printOp.id,values:{berkasid:data.berkasId}}});if(!current())return;print=searchFilePrint(printReply.result);}catch(error){if(!current())return;if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(error.code))throw error;}if(!current())return;data.fileSop=sop;data.statusCetak=print;owner.response={...primary.result,data:{data}};owner.sop=sop;owner.print=print;state.results.set(primaryOp.id,primary.result);owner.captcha=generateSearchFileCaptcha();owner.captchaInput='';record('Cari Berkas','success','Pencarian berkas selesai.');}catch(error){if(!current())return;if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(error.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(error.message);return;}owner.response=null;owner.sop=null;owner.print='-';owner.message=`Berkas tidak ditemukan. ${error.message==='Berkas tidak ditemukan.'?'':error.message}`.trim();owner.captcha=generateSearchFileCaptcha();owner.captchaInput='';record('Cari Berkas','error',`${error.code||'ERROR'} · ${error.message}`);}finally{if(current()){owner.busy=false;owner.request=null;renderSearchFile();}}}
function backSearchFile(){if(route!=='searchfile'||!state.authenticated||!searchFileState||searchFileState.busy)return;searchFileState.response=null;searchFileState.message='';renderSearchFile();}
